SY_TALK("D6i8r9WP6oc.hi",[[1058,["सहज योगी (श्री वारेन) - परम पूज्यनीय","श्री माताजी निर्मला देवी, दिल्ली वासियों"]],[1063,["और मेरे विदेशी भाइयों और बहनों, जो इस","महान देश भारत की यात्रा पर आए हैं -"]],[1069,["ईश्वर के साथ एक होने की उस ईमानदार","तड़प को सुनना बहुत सुंदर है"]],[1075,["वह सच्ची भक्ति कि, \"कृपया मुझे योग प्रदान करें,","कृपया मुझे भगवान का आशीर्वाद प्रदान करें,\" -"]],[1085,["यह कुछ ऐसा है जिसके हम पश्चिम में","इतने आदी नहीं हैं,"]],[1091,["और फिर भी, शायद यहाँ भारत में,","हम इसे थोड़ा हल्के में लेते हैं।"]],[1098,["श्री माताजी निर्मला देवी के पास इतनी विशेषताएँ हैं","- मुझे नहीं पता कि कहाँ से शुरू करूँ"]],[1105,["लेकिन संभवत: सबसे अच्छी शुरूआती जगह","और संभवत: सर्वोत्तम समापन स्थान"]],[1110,["है, कि वह यहाँ, साक्षात् मौजूद हैं। श्री माताजी","हमें आशीर्वाद देने के लिए यहाँ मौजूद हैं,"]],[1119,["जिसके बारे में हम भक्तगण अपने पिछले","जन्मों में बार-बार गाते रहे हैं।"]],[1125,["वह हमें आत्मसाक्षात्कार का आशीर्वाद","देने के लिए यहाँ हैं,"]],[1129,["वह हमारे भीतर की उस सूक्ष्म ऊर्जा को जगाने","के लिए यहाँ हैं, जिससे हमें हमारा दूसरा","जन्म प्राप्त होता है"]],[1139,["वह यहाँ, न केवल हिंदू शास्त्रों के बल्कि ईसाई","शास्त्रों के भी, सभी वादों को पूरा करने","के लिए आईं हैं,"]],[1146,["मुस्लिम धर्मग्रंथों तथा अन्य सभी","महान अवतार, जो इस पृथ्वी पर आते हैं","हमें आध्यात्मिक रूप से आगे बढ़ाने के लिए"]],[1155,["ईश्वर की खोज में। तो हमें किन बातों का ध्यान","रखना चाहिए और हमेशा याद रखना चाहिए"]],[1162,["इस जीवनकाल के दौरान वह यह है कि, यहाँ","हमारे पास व्यक्तिगत रूप से कोई हैं, जो","वास्तव में हमें दे सकतीं हैं"]],[1172,["वह उपलब्धि जिसकी हम कई जन्मों","से तलाश कर रहे हैं।"]],[1177,["हमारे तर्कसंगत दिमाग के लिए इस बात को","स्वीकार करना बहुत मुश्किल है।"]],[1182,["दूसरे शब्दों में, यह हमारे लिए बहुत कठिन है","अहंकार को उस हद तक समर्पण करना और","कहना,"]],[1188,["\"शायद यहीं हम मिले हैं, उनसे जो","हमारी सभी मनोकामनाएं पूर्ण करतीं हैं ।\""]],[1195,["श्री माताजी कोई दावा नहीं करतीं। वह यहाँ","एक माँ के रूप में हैं। हम अपने दिल से","विश्वास करते हैं"]],[1204,["और हमारे पास जो भी आंतरिक ज्ञान है, उससे","पता चलता है कि वह आदिशक्ति का अवतार है -"]],[1213,["लेकिन वह कुछ भी दावा नहीं करतीं हैं। वह एक","काम करतीं हैं । वह हमें ईश्वर का प्रेम उसके","शुद्ध रूप में देतीं हैं।"]],[1221,["वह हमें कुण्डलिनी की वह जागृति प्रदान","करतीं हैं, जिससे हमें वह योग प्राप्त होता","है, जिसके बारे में हम पढ़ते आये हैं,"]],[1229,["अपनी प्रार्थनाएँ गा रहे हैं, खोज रहे हैं,","इतने सारे जन्मों से।"]],[1236,["और जब हमें आत्म-साक्षात्कार मिल जाता है, तो","हम एक बहुत ही गतिशील व्यक्ति बनने लगते हैं।"]],[1241,["हम विज्ञान की वास्तविकता से अवगत होने लगते","हैं। अगर मैं एक डॉक्टर हूँ और मुझे केंद्रीय","तंत्रिका तंत्र के बारे में थोड़ा बहुत पता है,"]],[1250,["मैं विश्वास के साथ कह सकता हूँ कि, वह केंद्रीय","तंत्रिका तंत्र हमारे भीतर प्रबुद्ध हो जाता है।"]],[1257,["परानुकंपी तंत्रिका तंत्र, विशेषतः प्रभुत्वशाली","हो जाता है"]],[1262,["और हम अपने भीतर अपने सूक्ष्म अस्तित्व की","निगरानी करना शुरू कर देते हैं; लेकिन यह एक","बहुत ही स्थूल पहलू को देखना है।"]],[1270,["सूक्ष्म स्तर पर अपने भीतर हम सर्वशक्तिमान","ईश्वर के आनंद को महसूस करने लगते हैं।"]],[1275,["हम ईश्वर के आशीर्वाद को महसूस करना शुरू","कर देते हैं - महसूस करते हैं - बौद्धिक","रूप से नहीं बल्कि अनुभव से।"]],[1282,["हम उस 'अनाम' से सराबोर होने लगते हैं","जिसके बारे में बहुत से लोगों ने लिखा है,"]],[1288,["जिसके बारे में बहुत सारे व्याख्यान दिए गए हैं","और अब हम इसे महसूस करना शुरू करते हैं।"]],[1293,["हम उन्हें हजारों-हजारों लोगों को आत्म","-साक्षात्कार देते हुए देखते हैं"]],[1300,["महाराष्ट्र के गाँवों और कस्बों में","जहाँ वह हर साल दौरे आयोजित करती हैं -"]],[1305,["हममें से 200 लोग पिछले दो महीनों से उनके","साथ भारत के उस हिस्से के राजमार्गों और","सड़कों पर यात्रा कर रहे हैं,"]],[1313,["जहाँ हमने सचमुच पूरे गाँव, पाँच-छह-सात","हज़ार लोग देखे हैं;"]],[1318,["एक ही सत्र में अपना आत्म-साक्षात्कार प्राप्त","करते हुए। हाथों की बाढ़ देखना - \"हाँ,","मैं ब्रह्मशक्ति महसूस कर रहा हूँ;\""]],[1327,["\"हाँ, यही है! यही वो सच्चाई है जिसकी मैं इतने","लंबे समय से तलाश कर रहा था।\""]],[1332,["हम इस महान घटना के साक्षी हैं और हम","उनके चरण कमलों में नमन करते हैं।"]],[1337,["पश्चिम में, क्योंकि हम बहुत क्षतिग्रस्त हो चुके हैं,","क्योंकि हम अपनी खोज में इधर-उधर","भटक कर चले गए हैं,"]],[1346,["क्योंकि गुरुओं ने अपने झूठ से हमारे","आध्यात्मिक सार को नष्ट कर दिया है,"]],[1352,["क्योंकि हमने ईमानदारी से - अक्सर बहुत","मूर्खतापूर्ण तरीके से - इस राह या उस राह","जाकर तलाश की है,"]],[1356,["और बहुत ही मूर्खतापूर्ण लेकिन ईमानदारी से,","हमें अपना बोध प्राप्त हो जाता है।","कुंडलिनी स्वयं जागृत होती है"]],[1365,["बहुत बुरी तरह क्षतिग्रस्त चक्रों के माध्यम से -","लेकिन वह ऊपर उठती है, वह हमें संपर्क","में लाती है,"]],[1370,["वह सम्बंधित करती है और हम परमेश्वर के राज्य","में उस अंतिम आरोहण को प्रारंभ करते हैं।"]],[1377,["हम ईश्वर के राज्य में प्रवेश करते हैं, हम","द्वार से गुजरते हैं - ब्रह्मरंध्र से"]],[1384,["और जब ऐसा होता है, तो परिवर्तन शुरू होता है।","हम में से हर एक व्यक्ति एक संपूर्ण प्राणी","बन जाता है,"]],[1391,["हममें से हर कोई शारीरिक रूप से स्वस्थ","हो जाता है। हम माँ के पास आकर"]],[1395,["उनके चरणों पर बैठकर कहते नहीं , \"माँ, कृपया","मेरा गठिया ठीक कर दीजिए, कृपया यह ठीक","कर दीजिए, वह ठीक कर दीजिए"]],[1402,["मेरी मानसिक समस्याएँ, जैसा कि मैं समझता हूँ,","शायद आप में से कुछ करते हैं।"]],[1406,["हम अत्यंत आभारी हैं कि हमें यह मिल गया है।","हम तकनीक जानते हैं क्योंकि वह हमें","खाने में सक्षम हैं,"]],[1414,["क्योंकि अनजाने में ही हम उस तकनीक से","अवगत होने लगते हैं"]],[1418,["और हम जानते हैं कि कैसे हम अपने डॉक्टर","बनें और स्वयं का इलाज करें"]],[1423,["क्योंकि आत्म-साक्षात्कार के बाद क्या होता है","कि आप स्वयं अपने डॉक्टर, स्वयं अपने","गुरु बन जाते हैं,"]],[1428,["आप अपने खुद के मालिक बन जाते हैं।","आप पूरी तरह से स्वयं को नियंत्रित करते हैं।"]],[1434,["यह इस अवतार का आशीर्वाद है, जो","हमारे सामने हैं।"]],[1441,["मैं आप देवियों और सज्जनों को चुनौती देता हूँ कि","आप अपने अहंकार को, अपने तर्कसंगत दिमाग","को थोड़ी देर और शांत रहने दें,"]],[1448,["इस व्याख्यान श्रृंखला में भाग लें और","इन दिव्य स्पंदनों के प्रति खुले रहें।"]],[1454,["बस ब्रह्मशक्ति के प्रति खुले रहें, ताकि","संबंध स्थापित हो सके"]],[1459,["दृढ़ता से, ताकि कृपा का बहाव आपके चक्रों को","नहला सके, आपके भौतिक शरीर को","पुनर्स्थापित कर सके,"]],[1469,["आपको मानसिक शांति दे सके, आपको वह","'सत्-चित्-आनंद' दे सके। जय श्री माताजी!"]],[1496,["[MUSIC -BHAJAN]"]],[1507,["[MUSIC -BHAJAN]"]],[1521,["[MUSIC -BHAJAN]"]],[1538,["[MUSIC -BHAJAN]"]],[1548,["[MUSIC -BHAJAN]"]],[1566,["[MUSIC -BHAJAN]"]],[1582,["[MUSIC -BHAJAN]"]],[1606,["[MUSIC -BHAJAN]"]],[1625,["[MUSIC -BHAJAN]"]],[1646,["[MUSIC -BHAJAN]"]],[1672,["[MUSIC -BHAJAN]"]],[1685,["[MUSIC -BHAJAN]"]],[1703,["[MUSIC -BHAJAN]"]],[1721,["[MUSIC -BHAJAN]"]],[1738,["[MUSIC -BHAJAN]"]],[1762,["[MUSIC -BHAJAN]"]],[1782,["[MUSIC -BHAJAN]"]],[1845,["श्री माताजी: आज हिंदी में मैं भाषण दूँगी।"]],[1854,["परमात्मा को खोजने वाले सभी भाविक,","सात्विक साधकों को हमारा प्रणाम।"]],[1872,["आज दो तरह के गाने आपने सुने हैं। पहले गाने में","एक भक्त विरह में परमात्मा को बुलाता है -"]],[1882,["इसे अपरा-भक्ति कहते हैं, और जब परमात्मा","को पा लेता है, जैसे कबीर ने पाया था, तो","उसे परा-भक्ति कहते हैं।"]],[1894,["दोनों में ही भक्ति है। इसे कृष्ण ने अनन्य भक्ति","कही हुई है, जहाँ दूसरा कोई नहीं होता -","जहाँ साक्षात् परमेश्वर अपने सामने होते हैं।"]],[1907,["उस वक्त जो हम लोगों का भक्ति का स्वरुप","होता है, उसे उन्होंने परा भक्ति कही हुई है -","अनन्य भक्ति।"]],[1920,["किन्तु जब हम परमात्मा को याद करते हैं, उनको","स्मरण करते हैं, तब उसकी आदत सी हो जाती है।"]],[1931,["जब इंसान को इस चीज़ की आदत सी हो जाती है,","तो उस आदत से छूटने में उसे बड़ा समय","लग जाता है।"]],[1938,["वो यह मानने को तैयार ही नहीं होता है कि उसकी","ये जो साधना है ये ख़त्म होने की बेला आ गई है।"]],[1946,["और इसी वजह से भक्तों ने भी दृष्टों को,","संतों को, मुनियों को पहचाना नहीं।"]],[1955,["आप जानते हैं इतिहास में हमेशा संतों को","कितनी परेशानियों उठानी पड़ीं हैं।"]],[1964,["ये नहीं कि सबने उनको सताया, लेकिन जिन्होंने","सताया उनको किसी ने रोका नहीं और","उनको समझाया नहीं कि ये संत हैं, ये साधु हैं।"]],[1975,["अब हमारे समाज में, खासकर के शहरों में,","विविध विचारों के लोग रहते हैं।"]],[1985,["कुछ तो, क्योंकि परमात्मा में विश्वास करते हैं -","इस तरह विश्वास करते हैं जैसे कि किसी","मंदिर में गए नमस्कार कर दिया।"]],[1992,["कुछ लोग हैं जो कहते हैं, \"नहीं परमात्मा की","साधना करनी चाहिए और धर्म से रहना चाहिए,"]],[2002,["उनके मंगल गीत गाने चाहिए, हमेशा उनको","भजना चाहिए जिससे वो हमेशा याद रहें।\""]],[2010,["कुछ लोग ऐसे होते हैं कि जो कहते हैं, \"परमात्मा","वग़ैरा सब ढकोसला है, ये झूठी चीज़ है -"]],[2017,["परमात्मा नाम की कोई चीज़ ही नहीं है।\" सब","तरह के विचार करने का अधिकार परमात्मा ने","मनुष्य को दे दिया है।"]],[2026,["ये मनुष्य को दी हुई देन परमात्मा की ही है, कि वो","स्वतंत्र है; जो चाहे वो सोच सकता है इस बुद्धि से।"]],[2034,["लेकिन हम लोगों को तीनों भी दशा में ये सोचना","चाहिए, कि आज तक हमने जो कुछ भी किया"]],[2042,["चाहे परमात्मा में विश्वास किया, उनको भजा,","या उनके ऊपर लेक्चर दिए या उनपर किताबें पढ़ीं"]],[2049,["- जो भी मेहनत करी - या हमने उनपर विश्वास","नहीं किया, उनको कहा कि वो हैं नहीं,","उनसे हमने मुठभेड़ की"]],[2058,["और कहा कि, 'देखते हैं परमात्मा कहाँ हैं,' इन","सभी दशाओं में हमें ये सोचना चाहिए कि","इसने हमारा क्या भला किया,"]],[2069,["हमें क्या लाभ हुआ, हमारे अंदर कौन सी ऐसी","कोई नई प्रकृति आ गयी जिसके कारण हमने","जो भी किया सो ठीक है।"]],[2081,["हमारे बाप-दादे भी यही करते आये, और उनके","बाप-दादे भी यही करते आये, और हज़ारों","वर्षों से ये चीज़ चल रही है।"]],[2090,["सहज योग में हम लोग इड़ा और पिंगला,","दो नाड़ी पर ध्यान दे रहे थे।"]],[2097,["इसमें से जो इड़ा नाड़ी है, ये भक्ति प्रवीण है।","इड़ा नाड़ी पर लोग भक्ति में लीन हो जाते हैं,"]],[2105,["अपने भावना में बह जाते हैं और परमात्मा में लीन","हो कर के, आनंद से उनका गान गाते हैं।"]],[2115,["हमारे महाराष्ट्र में, जो कि मैं सोचतीं हूँ हिंदुस्तान","में एक बहुत बड़ा देश है, क्योंकि यहाँ पर","पारम्पारिक लोग धार्मिक हैं।"]],[2129,["और यहाँ का आराध्य देव श्री कृष्ण विट्ठल है।"]],[2134,["लोग एक-एक महीना हाथ में झांझर लिए हुए,","गाते हुए जाते हैं, 'विट्ठल, विट्ठल, विट्ठल,' -","मुँह में तम्बाकू रख के।"]],[2145,["अब तम्बाकू जो है, ये कृष्ण के विरोध है, बिलकुल","विरोध में पड़ता है क्योंकि विशुद्धि चक्र में","श्री कृष्ण का स्थान है।"]],[2153,["और उससे 'विट्ठल, विट्ठल' कह रहे हैं - श्री कृष्ण","का नाम ले रहे हैं - और उनका जो विरोध है","उसी को मुँह में रखे चले जा रहे हैं।"]],[2162,["ऐसे लोग बहुत से लोग मैंने देखे जो मुझसे","आके कहते हैं कि, \"माँ, हम तो ज़िन्दगी भर","विट्ठल ही की वारी करते रहे,"]],[2171,["हर बार वहाँ पैदल जाते रहे और एक-एक महीना","हमने मेहनत करी।\" बहुत से पढ़े-लिखे लोग भी","ऐसा कार्य करते हैं।"]],[2178,["\"लेकिन हमें तो परमात्मा मिले नहीं।\" एक","मुसलमान साहब थे जो कि बहुत","परमात्मा को खोजते थे।"]],[2185,["अंत में वो हिन्दू हो गए। उन्होंने कहा कि, \"परमात्मा","मुसलमान होने से तो मिलता नहीं, चलो हिन्दू","हो कर के मिल जाये तो देखें।\""]],[2191,["तो वो हिन्दू हो गए। हिन्दू हो कर के वो","इसी तरह से 'विट्ठल, विट्ठल' करते जाते थे।"]],[2197,["तो उन्होंने कहा कि, \"पहले तो नमाज़","पढ़-पढ़ के मेरे घुटने छिल गए थे,"]],[2203,["फिर वारी कर-कर के मेरे तलवे सब छिल गए,","और ये सब होते हुए मैंने ये देखा कि","परमात्मा तो मिला नहीं।"]],[2211,["जो विट्ठल के सामने लोग खड़े हैं, वो भी परमात्मा","के पास नहीं ,और जो लोग वहाँ जाते हैं,","वो भी परमात्मा के पास नहीं हैं।\""]],[2219,["हम लोग इसी प्रकार, हर समय कभी कोई अखंड","पाठ कर रहे हैं, कभी कोई परमात्मा को याद","कर रहे हैं -"]],[2226,["इस प्रकार हम अपनी भक्ति में परमात्मा","को याद करते रहते हैं।"]],[2230,["उससे एक चीज़ ज़रूर है कि परमात्मा","की तरफ हमारा चित्त है।"]],[2234,["नामदेव ने कहा है कि, एक लड़का अगर पतंग","उड़ा रहा है और पतंग आकाश में जा रही है।"]],[2243,["उधर सब बच्चे उसके साथ खेल रहे हैं, वो बातें","भी कर रहा है, सब से मज़ाक कर रहा है।"]],[2250,["और ये करते वक्त भी उसका चित्त उसी आकाश","के ऊपर तनाया हुआ जो उसका पतंग है","उसकी ओर है।"]],[2259,["इस प्रकार एक साक्षात्कारी मनुष्य का हो जाता","है कि उसका पूरा चित्त उसी ओर होता है।"]],[2266,["लेकिन जो नहीं हुआ, जिसने साक्षात्कार नहीं पाया,","उसके लिए उचित था कि वो परमात्मा","को याद करे।"]],[2276,["लेकिन ये सब करने से भी अगर परमात्मा को","याद किया और परमात्मा ही नहीं मिले -"]],[2281,["जैसे आपने कहा कि आकुल-व्याकुल लोग ढूँढ रहे","हैं परमात्मा को और उनको अगर परमात्मा","नहीं मिले"]],[2287,["तो ज़रूरी है कि मनुष्य कहेगा कि, \" हाँ,","परमात्मा नाम की कोई चीज़ नहीं है।\""]],[2293,["लेकिन क्योंकि हमें उसका अनुभव नहीं हुआ,","प्रचीति नहीं हुई, इसलिए उस चीज़ को पूरी तरह से","मना करना मेरे ख्याल से अशास्त्रीय है।"]],[2303,["उसको बगैर जाने बगैर, उसकी प्रचीति पाए बगैर,","उसको कह देना कि वो नहीं है,"]],[2309,["कोई सी भी चीज़, मेरे ख्याल से, एक तरह से","इसका पलायनवाद है - एस्केपिसिस्म।"]],[2318,["परमात्मा हैं, चाहे आप उसे माने या न माने।"]],[2322,["मैंने आपको बताया था कि ये फूल - इसको कौन","बनाता है, इन फूलों से फल कौन बनाता है,"]],[2327,["हमें अपने माँ-बाप जैसे कौन बनाता है, कौन","हमारे अंदर हमारे ह्रदय को चलाता है"]],[2334,["हमारे अंदर अनेक से ऐसे व्यवहार है जो मेडिकल","साइंस कभी भी समझा नहीं सकती कि कैसे होते हैं"]],[2339,["इसलिए मनुष्य भक्ति पर उतरता है","और परमात्मा को याद करता है।"]],[2344,["पिंगला नाड़ी पर जब हम आते हैं, तो वहाँ पर","मनुष्य ने ये सोचा कि परमात्मा ने जो सृष्टि","रची हुई है"]],[2351,["इस सृष्टि में जो पाँच पंच महाभूत हैं, जो","एलिमेंट्स हैं, उसके बारे में जानना चाहिए -"]],[2357,["उनपे प्रभुत्व पाया जाए तो उन्होंने यज्ञ आदि","वगैरा शुरू कर दिया, वेद वगैरा रचे गए"]],[2362,["पर वेद में भी बिलकुल शुरू में लिखा है कि, 'गर","वेद से अगर विद नहीं हुआ अगर उसकी प्रचीति","नहीं आयी तो सारा वेद परायण हो गया।"]],[2369,["इस भारतवर्ष की एक महिमा है, बहुत बड़ी महिमा","है। कोई कितना भी बड़ा शास्त्री हो, पंडित हो,"]],[2377,["वेद व्यास हो, कुछ हो, लोग उसके सामने हाथ","नहीं जोड़ें, पर अगर कोई संत हो, फ़क़ीर हो,"]],[2385,["हाथ में झोली लिए भी हो और संत हो, माना हुआ","संत हो, तो लोग उसके सामने झुक जाते हैं, फिर","वो राजा हो, चाहे वो कुछ भी हो।"]],[2394,["ये अपने देश की बड़ी महिमा है - ऐसे","आपको कहीं भी नहीं दिखाई देता है।"]],[2398,["ये इसी देश में होता है क्योंकि इस देश की","अपनी एक बड़ी विशेष पुण्याई है।"]],[2403,["यहाँ बड़े-बड़े पुण्यात्मा, धर्मात्मा, संत-साधु हैं।"]],[2407,["हमारी दृष्टि जो बाहर की ओर लग गई है, इससे","सबसे बड़ा प्रश्न खड़ा हुआ है, कि अब सबकी","दृष्टि अन्तर्मुख कैसी करें"]],[2414,["और सबसे पहले कि ये लोग जाने कि इसी देश में,","इसी महान देश में ही, ये सारा ज्ञान बसा हुआ है।"]],[2423,["अब जो भी मैं आपसे बता रहीं हूँ बातें, इसको","आप इस तरह से देखें, जैसे एक साइंटिस्ट के","सामने कोई हाइपोथिसिस रखा जाता है।"]],[2431,["अगर आप उसको इस दृष्टि से देखें तो आपको","समझ में आ जायेगा, कि जो मैं बातें कह रहीं हूँ,"]],[2437,["वो आपको पहले देख लेनी चाहिए, जान लेनी","चाहिए, फिर प्रचीति आने के बाद में"]],[2442,["उसको आपको जाँचना चाहिए कि ये बात","सत्य है या नहीं, परमात्मा है या नहीं।"]],[2448,["लेकिन पहले धारणा तो करनी पड़ती है, कि","धारणा तो करनी पड़ती है, कि ऐसी-ऐसी","बातें हैं, इसे सुनना चाहिए।"]],[2455,["उसी बात पर अगर आप उतरे हुए हैं, तो फिर","आगे बढ़ ही नहीं सकते।"]],[2458,["पहले इसे आप धारिए, जो मैं बात कह रहीं हूँ","उसको आप समझने का प्रयत्न करें।"]],[2464,["मैंने उस दिन आपसे इन तीनो नाड़ियों के","बारे में बताया हुआ था, संक्षिप्त में।"]],[2469,["आज मैं आपसे इनके अलग-अलग चक्रों के","बारे में आपसे बताना चाहती हूँ।"]],[2475,["आपके अंदर सात चक्र मुख्य हैं - ये नहीं कि सात","ही चक्र हैं। सात मुख्य चक्र माने जाते हैं।"]],[2482,["ये सब ज्ञान हमारे देश का है - मूल का ज्ञान","है - ये आपको किताबों में नहीं मिलेगा।"]],[2489,["ये बड़े-बड़े ऋषि मुनियों ने इसका पता लगाया है;","कुछ-कुछ इस पर किताबें भी हैं"]],[2493,["लेकिन बड़ी सकील तौर की हैं, और दूसरा ये","भी है, कि उपलब्ध भी नहीं हैं।"]],[2499,["ये सात चक्र हमारे अंदर ऐसे बनाये हुए हैं,","बढ़िया तरीके से, कि जैसे कि एक के बाद","एक हमारी सीढ़ी हो।"]],[2508,["ये सीढ़ियां हमारी उत्क्रांति में बनाईं हुईं हैं।","जब से हम कार्बन थे तब से लेकर के धीरे-धीरे"]],[2515,["जैसे हम उठने लग जाएँ, वैसे-वैसे हरएक उत्क्रांति","का जो एक-एक टप्पा हमने हासिल किया,"]],[2522,["उसके अनुसार ये जैसे कि ये एक-एक","माइलस्टोन बनाया गया है।"]],[2527,["सबसे पहले कार्बन का जो हमारे अंदर प्रादुर्भाव","हुआ, वो है पहला चक्र, जिसे कि","मूलाधार चक्र कहते हैं।"]],[2537,["इस चक्र के बारे में भी बहुत से लोगों को","बहुत गलत फहमियाँ हैं।"]],[2542,["कुण्डलिनी के बारे में तो जिसे देखिए वो ही","लिखने लग जाता है।"]],[2545,["मैंने ऐसी भी किताबें पढ़ीं हैं कि जिसको पढ़कर","आदमी कहेगा, कुण्डलिनी के पास जाने","की ज़रुरत नहीं है।"]],[2549,["एक साहब ने लिखा है कि उसको कुण्डलिनी","जागरण हो गया उसके अंदर बिजली","चमकने लग गई।"]],[2553,["किसी ने लिखा कि मेरे अंदर छाले आ गए।","किसी ने कहा मैं मेंढक जैसे कूदने लग गया।"]],[2559,["हिंदी में नहीं अंग्रेजी में भी ऐसी किताबें","बहुत छपी हुईं हैं।"]],[2562,["वास्तविक कुण्डलिनी आपकी माँ है। हरएक इंसान","की ये माँ है। अपनी एक-एक व्यक्तिगत माँ है।"]],[2571,["और ये माँ आपको आपका दूसरा जन्म देती है। ये","जो माँ है, ये माँ क्या आपको कोई तकलीफ़ देगी?"]],[2580,["जब आपका जन्म हुआ था तो आपकी माँ ने","आपको तकलीफ दी या सब तकलीफ खुद उठाई।"]],[2585,["फिर ये जो माँ, जो विशेष एक दैवीय माँ है, वो क्या","आपको तकलीफ़ देगी या आपको परेशान करेगी?"]],[2592,["बुद्धि से भी काम लेना चाहिए। जो लोग इस तरह","की बातें करते हैं या तो वो इस काबिल नहीं हैं","कि कुण्डलिनी पर कोई भी हाथ चलाएं।"]],[2602,["हो सकता है वो धर्मोपरायण न हों,अधर्मी हों,","उनके चरित्र अच्छे न हों, वो रुपया पैसा बनाते हों,"]],[2609,["लोगों को ठगते हों - हर तरह की उनमें","गड़बड़ियाँ हो सकतीं हैं।"]],[2614,["हो सकता है कि उनको इसके बारे में कुछ","भी जानकारी न हो।"]],[2618,["हो सकता है कि उनपे किसी ने कुछ भूत-प्रेत","विद्या करके उनको भस्मीसात कर दिया हो।","कुछ भी हो सकता है।"]],[2625,["लेकिन कुण्डलिनी जागरण से - आजतक हज़ारों","लोगों का कुण्डलिनी जागरण हो गया है","सहज योग से"]],[2631,["लेकिन हमने कहीं नहीं देखा कि लोगों में","ये परेशानी या तकलीफ़ होती हो।"]],[2637,["कुण्डलिनी खुद सूझ-बूझ रखती है - पूरी","तरह की सूझ-बूझ कुण्डलिनी के अंदर है।"]],[2642,["और जैसे कोई एक टेप रिकॉर्ड नहीं होता है, उसी","प्रकार ये साढ़े तीन वलय में इसने आपका","पूरा इतिहास लिखा हुआ है।"]],[2650,["जब से आप कार्बन थे तब से आज तक का","पूरा इतिहास इसके अंदर है।"]],[2655,["ये जानती है कि आपने क्या-क्या गलतियाँ कीं,","आप कौन से गलत रस्ते पर गए,"]],[2660,["आपने क्या-क्या अपने साथ दुर्व्यवहार किया है,","दूसरों के साथ दुर्व्यवहार किया है,"]],[2665,["क्या-क्या आपने ऐसे काम किये हैं जो परमेश्वर के","मार्ग में एक तरह से रुकावटें हो सकतीं हैं,"]],[2672,["बाधक हो सकतीं है - वो सब कुछ वो जानती है।","उसके पास इसका हिसाब-किताब पूरा है।"]],[2677,["लेकिन वो आपकी माँ है। माँ ये नहीं सोचती","कि मेरा बेटा कितना दुष्ट है।"]],[2682,["वो ये सोचती है, कि किस तरह से इस बेटे को मैं","जो है, तो उसका जो धन है, उसे दे दूँ, किस","तरह से इसे मैं बचा लूँ।"]],[2690,["माँ का ये नहीं विचार आता - समझ लीजिए","किसी का बच्चा डूब रहा हो, तो माँ ये नहीं सोचती,"]],[2694,["कि, इसने मेरे साथ क्या-क्या दुष्टता की, इतना","सताया - वो सोचती है जो भी हो सब माफ़, मेरा","इस वक्त बच्चा है बचा लें।"]],[2701,["इसी प्रकार ये माँ आपकी यही सोचती है कि","आपको किसी तरह बचा लिया जाए।"]],[2707,["लेकिन इस माँ के लिए आपका जो बाल्यावस्था","में आपका पाया गया हुआ अबोधिता का धन है,"]],[2717,["जिसे हम इनोसेंस कहते हैं, वो वहाँ पर नीचे","स्थित है, जहाँ पर कि इसे मूलाधार चक्र कहते हैं।"]],[2725,["ये जो कुण्डलिनी ऊपर है और मूलाधार चक्र नीचे","में है - कुण्डलिनी स्वयं मूलाधार में बसी हुई है।"]],[2732,["मूलाधार जो है, वो है कि जिसे कहते हैं कि मूल","का आधार। अगर मूल कुण्डलिनी है, तो"]],[2740,["उसका आधार, माने उसका गृह, उसका घर जो है","वो आपकी ये त्रिकोणाकार अस्थि है,"]],[2747,["और उसके नीचे गणेश तत्व जो बसा हुआ है,","वो आपके अंदर बसी हुई अबोधिता है।"]],[2754,["आजकल तो चालाकी करना, होशियारी दिखाना,","बदतमीज़ी करना या ऐसा कहें, कि अपने चरित्र","के साथ हर समय विडम्बना करना"]],[2764,["ये एक तरह का लोगों का बड़ा शौक हो गया है।","लोग सोचते हैं कि इसमें उन्होंने बहुत कुछ","कमा लिया।"]],[2771,["अपनी पवित्रता के साथ छलना करना, अपने","सादगी के साथ हमेशा कोई न कोई","उपाधि लगा देना,"]],[2780,["इस पर हमारा बड़ा विचार चलता है कि","किस तरह से कैसे क्या किया जाए।"]],[2786,["ये चक्र जो है हमारे अंदर बहुत महत्वपूर्ण है","- हालाँकि इस देश में ये चक्र बहुत बलवान है।"]],[2795,["क्योंकि कुछ भी हो इस देश में","पवित्रता का अर्थ लोगों को मालूम है।"]],[2800,["लोग गलत काम करते हैं लेकिन वो जानते हैं","कि ये गलत है।"]],[2804,["लेकिन परदेस में मैंने देखा, कि वो गलत काम","करते हैं, इस तरह से विचित्र बातें करते हैं,"]],[2811,["कि समझ में नहीं आता कि ये इंसान हैं","या जानवर हैं।"]],[2815,["और वो ये सोचते हैं कि उन्होंने बड़ी कमाई कर ली,"]],[2818,["वो तो एकदम फ्रीडम पे आ गए, उन्होंने बहुत कुछ","पा लिया कि इस तरह के गंदे काम वो कर रहे हैं।"]],[2824,["श्री गणेश, विशेष कर के, जो बनाये गए हैं, उनका","रूप ऐसा है कि उनके सिर पे हाथी का सिर है।"]],[2832,["वजह ये कि एक हाथी एक पशु है और पशु","कभी भी अहंकार एकत्रित नहीं करता है।"]],[2840,["इसीलिए उसके अंदर अहम् की भावना नहीं आती","है। वो चिर का बालक है और गणेशजी","चिर के बालक हैं।"]],[2847,["लेकिन उनके अंदर जो आयुध है और जो","विशेष तरह की उनके पास में व्यवस्थाएँ हैं,"]],[2853,["उन सब व्यवस्थाओं से वो मनुष्य के अंदर जो","पेल्विक प्लेक्सस है उसको सँभालते हैं।"]],[2860,["पर ये इतने शक्तिशाली हैं कि गर आप किसी भी","तरह से कुंडली पर आघात करने का प्रयत्न करें"]],[2866,["या जो आदमी धर्मरहित है, जिसमें चरित्रहीनता है -","ऐसा आदमी कोशिश करे कि कुण्डलिनी को चढ़ाये"]],[2873,["वो इस कदर नाराज़ हो जाते हैं कि आप देख","रहे हैं यहाँ पर कि सबसे नीचे बैठे हुए हैं"]],[2879,["लेकिन इसके साथ में इड़ा नाड़ी ऊपर जुडी हुई","है, उस इड़ा नाड़ी पर इनका क्रोध जब चढ़ता है,"]],[2885,["तो आदमी के यहाँ से लेकर यहाँ तक सारे","ब्लिस्टर्स भी आ सकते हैं।"]],[2889,["ऐसा आदमी गर्मी से तड़प सकता है,","उसको तकलीफ़ हो सकती है।"]],[2895,["ये गणेश का तत्व जो है जितना सुखदाई है,","उतना ही क्षोभकारी है। अत्यंत क्रोधवान!"]],[2904,["इस भारतवर्ष में, गणेश आठ, अष्टविनायक, आप","जानते हैं, कि जागृत पृथ्वी के तत्व से निकले हैं।"]],[2912,["अब हम लोग मानते तो हैं, कि सब ये वैष्णो देवी,","वहाँ जाना चाहिए, इस मंदिर में जाना है,","उस मंदिर में जाना है"]],[2918,["लेकिन ये जागृत तत्व क्या हैं - क्या हम जानते","हैं कि ये जागृत तत्व क्या है?"]],[2922,["क्या ऐसी कोई सच्ची बात है कि वास्तविक","कोई ऐसे जागृत तत्व का कोई स्थान है?"]],[2928,["ऐसा स्थान है - क्योंकि पृथ्वी तत्व जो है,","ये स्वयं साक्षात् जागृत है।"]],[2933,["आपको आश्चर्य होगा, मैं एक छोटी सी जगह","मुसलवाड़ी में गयी थी, वहाँ पर लोगों ने मुझे बताया"]],[2939,["कि ये जागृत स्थान है और वहाँ पर कोई भी","दीवार नहीं बना सके।"]],[2945,["एक अंग्रेज वहाँ लिख गए कि इस अजीब सी","जगह है, यहाँ आप कोई दीवार नहीं बना सकते,","कोई बंध नहीं बना सकते,"]],[2951,["तो बंध को ऐसे सीधे लेने की जगह ऐसे गोल","घुमा दिया और फिर इस तरह से लिया।"]],[2956,["और पता ये हुआ कि ये जगह - एक फ़कीर ने आ","के बताया - कि ये जगह माँ की है","इसे छोड़ दीजिए।"]],[2964,["जब हम जा के, हम लोगों ने देखा तो उसके अंदर","से चैतन्य की लहरियाँ ठंडी-ठंडी लहर सी","चल रहीं हैं।"]],[2971,["साक्षात् सारा सहस्त्रार खुला पड़ा है। लेकिन ये","सिर्फ एक फ़क़ीर या कोई संत या साधु या","सहज योगी बता सकता है।"]],[2980,["जिसको इसकी अनुभूति नहीं है, वो नहीं बता","सकता है कि ये चीज़ जागृत है, या ये झूठ है,","या ये आदमी सच है, या झूठ है।"]],[2988,["इसके लिए आपको वो ऊँची संवेदना, जिसे कि","हम लोग सामूहिक संवेदना कहते हैं, उसमें","जागृत होना पड़ेगा।"]],[2997,["फिर मैं कहूँगी कि आपको जागृत होना पड़ता है,","सिर्फ लेक्चर बाज़ी से नहीं होता है।"]],[3001,["आपको होना पड़ेगा। जब तक आप इसमें प्राप्त न","होंगे, जब आप के अंदर इसकी प्रचीति नहीं आएगी,"]],[3009,["जब तक ये आपको विद नहीं होगा, तब तक आपमें","और उन साक्षात्कारियों में हमेशा अंतर बना रहेगा।"]],[3019,["इस चक्र के विशेषता ये है, कि जब","कुण्डलिनी का जागरण होता है -"]],[3025,["जैसे आप मेरे ओर ऐसे हाथ इस वक्त करके बैठें तो","अच्छा रहेगा - भाषण करते ही काम हो सकता है,"]],[3030,["और पैर से जूते उतार लीजिए। आप जिस वक्त","मेरी ओर इस तरह से हाथ करके बैठे हुए हैं,"]],[3036,["तब आपके ये जो पाँच यहाँ पर उँगलियों में ये","सिम्पैथेटिक नर्वस सिस्टम (तंत्रिका तंत्र)","के एंड्स हैं,"]],[3042,["ये छह और ये सात - इस प्रकार सात चक्र लेफ्ट","साइड में और सात चक्र राइट साइड में हैं।"]],[3049,["अब ये जो सात चक्र हमारे लेफ्ट और राइट में हैं,","जैसे मैंने बताया था, इस तरह से मिल जाते हैं,"]],[3054,["और सुषुम्ना नाड़ी ऐसे बीच में तैयार हो जाती है","- मैंने आपसे पिछले लेक्चर में बताया है।"]],[3060,["अब जब आप मेरी ओर हाथ करके बैठे हैं, तो","धीरे-धीरे, धीरे-धीरे इसमें से चैतन्य","बहना शुरू होता है।"]],[3067,["जब चैतन्य बहना शुरू हो गया तो वो जाकर के","वहाँ पर श्री गणेश को ख़बर देता है कि अब","कोई अधिकारी सामने खड़े हैं।"]],[3076,["ये अधिकार आपको स्कूलों में, कॉलेजेस में, या","किसी थियोसोफिकल सोसाइटी में,"]],[3082,["या थिओलॉजी में या पठनादि से - किसी से","भी नहीं आता है।"]],[3087,["ये अधिकार जो है ये साक्षात्कारी मनुष्य","को ही अधिकार है।"]],[3092,["जब ऐसा व्यक्ति जो जानकार है उसके सामने आप","इस प्रकार हाथ फैलाते हैं, तो गणेशजी को","पहले इसका न्योता मिलता है"]],[3103,["कि आप कुण्डलिनी से अब कहें कि आपको","निमंत्रण है और आप चढ़ें। गणेशजी के बगैर","ये काम नहीं हो सकता है।"]],[3111,["अब किसी डॉक्टर से ये कहा जाए कि गणेशजी","जो हैं ये आपके प्रोस्ट्रेट ग्लैंड को देखते हैं,"]],[3118,["या सँभालते हैं, संवारते हैं, तो कहेंगे, 'क्या","बात कर रहे माताजी, गणेशजी और","मेडिकल का क्या सम्बन्ध है?'"]],[3125,["मेडिकल साइंस जो है ये तो ऊपर में है, लेकिन","उसके जड़ में अगर श्री गणेश बैठे हैं,"]],[3132,["तो एक मिनिट अपने बुद्धि से ये पूछें कि, 'अगर","इससे हमारे प्रश्न अगर किसी तरह से","सुलझ सकते हैं,"]],[3140,["तो क्यों न हम इस इस चीज़ को समझें कि","श्री गणेश क्या हैं और उनका हमारे अंदर","जागृत होना कितना ज़रूरी है।"]],[3147,["एक महाशय थे वो हमारे पास आये और कहने लगे","कि, \"माँ, मुझे प्रोस्ट्रेट की तकलीफ हो गई है,","डॉक्टर कहते हैं ऑपरेशन करो।\""]],[3154,["वो बड़े सहज योगी थे दूसरे गणेश भक्त। मैंने कहा,","\"आप इतने बड़े गणेश भक्त हैं, आपको कैसे"]],[3159,["प्रोस्ट्रेट हो गया? मेरी समझ में नहीं आता है,","क्या गणेश आपसे नाराज़ हो गए हैं?\""]],[3164,["कहने लगे, \"माँ, पता नहीं, मैं तो बड़ी","गणेश की भक्ति करता हूँ।\""]],[3167,["मैंने कहा, \"अच्छा, ल्यो भई चना खाओ। आज","हमारा प्रसाद चना है, चना खाइए।\""]],[3173,["तो इधर-उधर देखने लग गए। मैंने कहा,","'आना-कानी क्यों कर रहे हैं?'"]],[3177,["कहने लगे, 'आज संकष्टी है और संकष्टी","में उपास करता हूँ।'"]],[3180,["मैंने कहा, \"ल्यो, यही तो वजह है। जिस दिन","गणेशजी का जनम हुआ उस दिन","आप सूतक रख रहे हैं।"]],[3185,["ये किसने आपसे बताया कि जिस दिन","जनम हो, उस दिन आप उपास रखें?\""]],[3189,["अब धर्म में कितने दोष हैं देख लीजिए। बहुत","से लोग कहते हैं कि, 'धर्म हम इतना करते हैं,","हम इतने धार्मिक हैं माँ, तो भी हम बीमार हैं।'"]],[3197,["अब देखिए एक छोटा सा दोष देख लें, कि जब राम","का जनम होता है तब उपास करें,"]],[3202,["कृष्ण का जन्म होगा तब उपास करेंगे और नरक","चतुर्दशी - जिस दिन नर्क का द्वार खुलता है -"]],[3207,["उस दिन बैठ कर सवेरे खाना खाएंगे।","सब उलटी बातें, बिलकुल उल्टी बातें।"]],[3212,["ये पता नहीं किसने सिखाया। जिस दिन आपके","घर में बेटा पैदा होगा, उस दिन आप क्या","उपास करेंगे?"]],[3218,["जिस दिन दत्तात्रेय पैदा हुए उस दिन उपास।","कोई भी देख लीजिए जिस का भी जनम हुआ","उस दिन उपास करते हैं।"]],[3224,["उस दिन उपास करने की क्या ज़रुरत है,","मेरी समझ नहीं आता है।"]],[3228,["दूसरा ये कि परमात्मा के नाम पर क्यों उपास करते","हो। उसने कब कहा था कि आप उपास करिए।"]],[3232,["आपको करना हो आप करिए। आप अपने","शौकिया आपको उपास करना है, करिए।"]],[3237,["क्या इस देश में तो ऐसे ही लोग उपास में रहते हैं।"]],[3240,["लेकिन धर्म में हम इतनी गलतियाँ करते हैं और","बिल्कुल नासमझी से - जिसने जैसा कर दिया","- स्त्रियाचार।"]],[3246,["स्त्रियाचार और ब्राह्मणाचार्य की वजह से","हमारे धर्म में भी इतने दोष आ गए हैं।"]],[3251,["वो ही हाल मुसलमानों का है, वही हाल ईसाईयों","का है, वही हाल सिक्खों का है - सब का","एक ही हाल है।"]],[3257,["कि अपनी बुद्धि से उसको हम समझते नहीं हैं","कि किस वक्त क्या करना चाहिए।"]],[3264,["अब इनसे मैंने कहा कि, 'आप खाइए।' आपको","विश्वास नहीं होगा उन्होंने वो खाया।"]],[3269,["मैंने कहा, \"आप छोड़िए। आज से आप ये प्रॉमिस","करिए कि संकष्टी के दिन आप मोदक","बना के खाएँगे।\""]],[3276,["\"क्योंकि उनको मोदक प्रिय है, इसलिए आप","मोदक बना के खाइए।\""]],[3279,["तो उन्होंने कहा कि, \"अच्छा माँ, मैं आपको पूरा","प्रॉमिस देता हूँ कि मैं मोदक खाऊँगा।\""]],[3283,["आपको आश्चर्य करेंगे कि उनका प्रोस्ट्रेट, पूना","वो पहुँचे और उन्होंने चिट्ठी भेजी कि,","\"माँ, मेरा प्रोस्ट्रेट गायब।\""]],[3289,["उसकी तकलीफ़ ही गायब हो गई। इसी प्रकार हम","धर्म में अनेक, अनेक, अनेक गलतियाँ करते हैं।"]],[3298,["और इसीलिए जब हम कहते हैं कि, 'हमने धर्म","धारण किया, हम ये करते है, वो करते हैं,","फिर माँ हमें क्यों नहीं है।'"]],[3304,["इसका परमात्मा पे कोई दोष मत दीजिये। दोष","है जिसने आप को समझाया और बताया।"]],[3309,["जैसे कि लोग बताते हैं कि, \"जब कुण्डलिनी जागरण","होता है तो बड़ी गर्मी होती है और ऐसा होता है","और वैसा है।\""]],[3315,["सब झूठ है, एकदम झूठ। ऐसा कुछ भी नहीं।","इस बात पे आप बिलकुल मत विश्वास रखिए।"]],[3320,["ये लोग सब पैसा बनाने वाले आपको डरा, डरा","कर के और ऐसा दिखाते हैं, कि ये बड़े","कहीं के पहुँचे हुए लोग हैं।"]],[3327,["और इस तरह से आपको गलत रास्ते पर डाल देते","हैं और आप फिर ये पूँछने लग जाते हैं कि,"]],[3332,["'भई हमारा कुण्डलिनी जागरण हुआ, उससे तो","हमारी हालत ही ख़राब हो गई, हम तो","पागलख़ाने पहुँच गए।'"]],[3337,["होना ही हुआ, क्योंकि वो कुण्डलिनी का","जागरण नहीं है।"]],[3341,["वो आपकी सिम्पैथेटिक नर्वस सिस्टम की ओवर","एक्टिविटी हो जाती है, जिससे आप पागल","हो सकते हैं।"]],[3349,["अब श्री गणेश के बाद मैंने आपसे बताया था, कि","ये जो चक्र है जिसे कि हम स्वाधिष्ठान चक्र कहते हैं,","इसके बारे में आपसे मैंने पहले बताया हुआ है।"]],[3357,["उससे ऊपर में जो चक्र है, वास्तविक ये चक्र है,","यही दूसरा चक्र है, जिसे नाभि चक्र कहते हैं।"]],[3364,["क्योंकि इसी चक्र से स्वाधिष्ठान चक्र बाहर निकल","कर के, कमल जैसा निकलता है और चारों","तरफ घूम-घूम कर के,"]],[3371,["और ये जो बीच में जो जगह बानी हुई है जिसे कि","भवसागर कहते हैं - अपने पेट की जो जगह है"]],[3377,["जिसे विसेरास कहते हैं - इसके पूरी इसको वो","जितने भी उसमें इंद्रियें हैं, जितने भी उसमें","ऑर्गन्स हैं, सबको वो शक्ति देते हैं।"]],[3389,["उसके बारे में आपसे मैंने पहले बताया था कि","डायबिटीज आदि बीमारियाँ कैसे होतीं हैं।"]],[3394,["लेकिन आज मैं उससे जो उसके जड़ में जो चक्र","है, जिसे कि नाभि चक्र कहते हैं, उसके बारे","में बताऊँगी।"]],[3401,["नाभि चक्र जो है, ये विष्णु का चक्र है, नारायण","का चक्र है। अब कोई कहेगा कि, 'माँ,","अब तो सब हिन्दू धरम में क्या?'"]],[3413,["लेकिन और भी लोग, बहुत सारे, सभी इसी से","निवृत्त हैं। ईसा मसीह ने भी कहा है कि,"]],[3419,["\"दोस हु आर नॉट अगेंस्ट मी आर विद मी\"","(जो मेरे विरुद्ध नहीं हैं, वे मेरे साथ हैं)"]],[3422,["पर ईसाई लोग ये जाके पता नहीं लगाएँगे","कि और वो कौन हैं।"]],[3426,["उन्होंने तो बना लिया कि ईसा के सिवा","और कोई नहीं।"]],[3429,["इस्लाम ने बना लिया कि मोहम्मद के सिवा और","कोई नहीं। इस तरह से उन्होंने सब को एक-एक"]],[3435,["छाँट-छाँट के अलग कर दिया जिससे जैसे कि एक","आदमी लटका हुआ कहाँ पड़ा हुआ था।"]],[3439,["सब की रिश्तेदारी आपस में है। सिर्फ हमीं लोग","उनके नाम ले ले कर के झगड़ा करते हैं।"]],[3444,["अब इस चक्र के आस-पास आप देखिए कि जो","ये पेट का हिस्सा है इसमें दस गुरु के तत्व हैं।"]],[3451,["इसमें से आप सोच सकते हैं कि शुरू से","आदिनाथ से लेकर के अनेक गुरु हुए"]],[3456,["जैसे सॉक्रेटीस हैं, लाओत्से, ये सब इसी","में आते हैं। मोसस हैं, अब्राहम हैं,"]],[3460,["और अपने देश में राजा जनक, नानक, मोहम्मद","साहब और जोरास्टर और अभी आखिरी वक्त","जो हुए हैं, वो हैं, श्री साईं नाथ शिरडी के।"]],[3474,["ये सब इनके अवतरण, दस मुख्य अवतरण हुए,","वैसे तो अनेक गुरु हुए हैं संसार में, लेकिन","दस मुख्य अवतरण हुए।"]],[3485,["अब जो लोग गुरु को मानते हैं कि गुरु को मान लें।","अब देखिए, गुरु को मान लेना भी एक बड़ी","गलत फ़हमी की बात है।"]],[3493,["गुरु वही जो साहिब से मिलाए, जो साहिब","से मिलाए। जो परमात्मा से मिलाए, वही गुरु है।"]],[3504,["लेकिन हमारे यहाँ तो हर तरह के गुरु निकल","आये हैं और आप जानते हैं कि हम इतने","विक्षिप्त हो गए हैं,"]],[3510,["इतने भ्रान्तमय हो गए हैं, कि कोई भी आदमी","जेल से छूट कर के और बैठ जाये गेरुआ वस्त्र","पहन के, लगे उसके चरण छूने।"]],[3519,["पहली तो बात ये है कि गेरुआ वस्त्र से हमारा","क्या सम्बन्ध है - हम तो गृहस्थ के लोग हैं।"]],[3525,["गृहस्थियों का गेरुआ वस्त्र से कोई","भी सम्बन्ध नहीं होना चाहिए।"]],[3529,["आप जानते हैं अगर आपने पढ़ा हो कि वाल्मीकि","की रामायण में सीताजी ने पूरा चैप्टर इन","सन्यासियों के बारे में कहा है।"]],[3536,["कि जो सन्यासी है उनको शहर में तो आना ही","नहीं चाहिए किसी गाँव में नहीं आना चाहिए।"]],[3541,["उसकी बहुत सारी मर्यादाएँ बताईं। उसमें से","ये कहा कि गाँव के बाहर उन्हें झोपडी","में रहना चाहिए"]],[3548,["और किसी भी गृहस्थ की ड्योढ़ी लाँघनी नहीं","चाहिए। हाँ जो गृहस्थ है वो गृहस्थ है,"]],[3557,["लेकिन जिसने सन्यास ले लिया, उसको ये","सब करने का मना है।"]],[3561,["लेकिन हमारे यहाँ तो देखिए, कि हम लोग,","गृहस्थी के लोग यज्ञ कर्म में लगे हुए हैं,"]],[3566,["अपने बाल-बच्चों को सँभालते हैं, कायदे से रहते हैं,","और इन लोगों का पालन-पोषण हमारी","खोपड़ी पर।"]],[3572,["एक तो हमारे बाल बच्चे ही पलते नहीं, ऊपर से","इन काषाय वस्त्र वालों को सँभालते बैठे","रहिए सुबह से शाम तक।"]],[3578,["एक सीधी बात ये है कि कोई भी सन्यास लेने से","परमात्मा के पास नहीं जा सकता है।"]],[3584,["ये तो ऊपरी चीज़ है। सन्यस्त अंदर का भाव","होता है बाहर का नहीं होता है।"]],[3588,["आप जानते हैं कि राजा जनक को विदेही कहा","करते थे और उनकी लड़की को वैदेही","क्योंकि विदेही से पैदा हुईं।"]],[3595,["वो स्वयं राजा थे, राजा जैसे रहते थे, राजा जैसा","आभूषण करते थे, और उनको लोग बड़े-बड़े साधु,","संत, दृष्टा उनके सामने नतमस्तक रहते थे।"]],[3607,["क्योंकि उनकी दशा ये थी, क्योंकि वो स्वयं साक्षात्","दत्तात्रेय के अवतरण थे। गुरु के अवतरण थे,","आदि गुरु के अवतरण थे।"]],[3616,["लेकिन आजकल हमारे देश में इसकी संवेदना","जाती नहीं है। लोग भ्रांत हो गए हैं,"]],[3622,["बहुत ही भ्रांत हो गए हैं, और ऊपरी तरह से कोई","ऊपर से दिखाने वाला, कोई तमाशा वाला","आदमी पहुँच जाये,"]],[3628,["तो लोग उसके चरणों में पहले जाते हैं। कोई","न कोई तमाशा वो करना जानता हो।"]],[3632,["किसी भी तमाशे के पीछे में भागना हम लोगों","में एक स्वभावता एक बात हो गई है।"]],[3636,["कि कोई तमाशखोर पहुँच जाये तो उसके","पीछे में हम भागते हैं।"]],[3639,["फिर हज़ारों लोग उसके चरण में जाएँगे, अरे भाई,","और फिर झूठी-झूठी बातें उसके बारे में फैलाना,"]],[3645,["कि 'उसने इस आदमी को ठीक कर दिया,","वो ठीक हो गया, उनको शांति मिल गई।'"]],[3650,["इस तरह की गलत फहमियाँ। बहुत से लोग कहते","हैं कि, 'हम उन गुरु के पास गए थे, हमको","शांति मिल गई।'"]],[3656,["मैंने कहा, \"कैसी शांति मिली है, आपको","शमशान शांति मिली हुई है।\""]],[3659,["\"अब आप हिल ही नहीं सकते हो। आपको अशांति","तो है ही लेकिन वो अशांति जो है,"]],[3664,["अब एकदम जम के पत्थर हो गई,","अब आप हिल नहीं सकते।\""]],[3667,["ऐसी ही व्यवस्था हो गई। क्योंकि ये लोग जो धंधे","करते हैं, जिस तरह से ये काम करते हैं,","ये आप जानते हैं।"]],[3675,["हम तो काफी उमर वाले हैं और हम सब जानते थे","इसके बारे में। अब तो आप लोग सब","यंगर जनरेशन के लोग हैं,"]],[3682,["शायद आपने जाना ही नहीं होगा, कि भानामती,","और शमशान विद्या, प्रेत विद्या, तांत्रिक","विद्या अपने देश में बहुत है।"]],[3689,["इस समय, कुछ मुझे लगता है कि, दिल्ली के लोगों","का मन तांत्रिकों से कुछ हटा हुआ है।"]],[3694,["नहीं तो जहाँ जिस गली में जाइए, वहाँ एक","तांत्रिक बैठा हुआ था इसमें - आपके राजधानी में"]],[3700,["इस तांत्रिकों के शौक ने आपको भ्रांत कर","दिया है और इसमें आप फँस गए हैं।"]],[3707,["ऐसी छोटी-छोटी चीज़ों के पीछे में भागने","वाले लोग परमात्मा को कैसे पाएँगे?"]],[3712,["अगर माँगना है तो कोई परम चीज़ माँगनी चाहिए","और परम में ही सब कुछ मिल जाता है।"]],[3717,["क्योंकि श्री कृष्ण ने कहा है कि, 'योगक्षेम वाहमयं' -","पहले जब योग होगा, तो तुम्हारा पूरी तरह","से क्षेम होगा।"]],[3724,["कोई महाशय कहता है कि, 'माँ, मेरी तंदरुस्ती","अच्छी नहीं है।'"]],[3728,["मेरे पास बहुत से पहलवान आते हैं, कहते हैं,","\"माँ, हमें तो कोई शांति नहीं जीवन में।\""]],[3732,["कोई आदमी कहता है, \"माँ, मेरे पास पैसा नहीं है।\"","दूसरा रईस आदमी आता है कहा, \"मुझसे तो दुखी","कोई दुनिया में है नहीं।\""]],[3738,["इसका मतलब ये है कि सब संसार दुखी है और","इस दुखी संसार में आप अगर किसी को ये सोचें"]],[3747,["कि दूसरे के पास कोई चीज़ है तो उससे","वो सुखी है ये आपको ग़लतफहमी है।"]],[3752,["आप इस पर विश्वास करें कि जिस मनुष्य को आप","सुखी समझते हो वो महा दुखी हो सकता है।"]],[3757,["लेकिन आपको पता नहीं। इसलिए जिस चीज़ को","आप माँग रहे है उससे आपको सुख","नहीं होने वाला।"]],[3762,["आपको जिस चीज़ को माँगना है उसे माँगें, और वो","है परम, और वो परम तत्व आप ही के अंदर है","जिसको आपको पाना है।"]],[3770,["उसके लिए कहीं जाने की ज़रुरत नहीं, किसी से","कुछ देने की ज़रुरत नहीं। कुछ उसमें","आडम्बर नहीं है।"]],[3776,["बहुत सीधी सरल चीज़ है। जैसे कि एक बीज को","आप अंकुर ला सकते हैं अगर माँ के उदर","में डाल दें,"]],[3784,["उसी प्रकार ये कार्य हो सकता है। लेकिन मनुष्य","के लिए सीधा-साधा होना भी कठिन हो गया है।"]],[3790,["क्योंकि वो सीधे इधर से खाना खाना अब जानता ही","नहीं। इधर से हाथ फिरा के ही वो खाना खाता है।"]],[3795,["कोई काम सीधे तरीके से करना उसके बुद्धि के परे","हो गया है - उसकी बुद्धि इतनी जटिल हो गई है।"]],[3800,["सोच-सोच कर के उसका दिमाग खराब हो गया","है। इस गुरु के कारण कैंसर जैसी बीमारियाँ","होतीं हैं।"]],[3808,["गलत गुरु के सामने आपकी पेशानी - इसीलिए","सब ने कहा है, 'अपनी पेशानी सब के सामने","मत झुकाओ।'"]],[3813,["यहाँ तक कि मंदिरों में जब आप जाते हैं, कोई भी","आदमी आपको अगर टीका लगा दे तो (अस्पष्ट)।"]],[3820,["हरएक आदमी से आप अपने माथे पे टीका","लगा लेते हैं - बहुत बड़ा दोष है।"]],[3824,["किसी का क्या अधिकार है कि आपके माथे को","छूए। आप जानते हैं कि आपने तो कहा कि,","'नौ-दस साल बिनन को लागे,'"]],[3830,["मैं कहती हूँ कि ये तो हज़ारों वर्षों से आपको","बना-बना करके कर आज परमात्मा ने"]],[3835,["मनुष्य बनाया हुआ है, और उसको आप किसी","के भी सामने सिर झुका देते हैं।"]],[3839,["किसी के सामने भी सिर झुकाने को हमेशा","लोगों ने मना किया है।"]],[3843,["सिर्फ साक्षात्कारी जो आदमी है, वही जानता है","कि किसके सामने सिर झुकाना चाहिए।"]],[3848,["हम तो कहते हैं कि हमारे भी पैर छूने की आपको","कोई ज़रुरत नहीं - और न छुओ तो अच्छा है।"]],[3852,["जब तक आप पार नहीं हुए, जब तक आपके हाथ","में चैतन्य नहीं आया, हम आपके लिए वैसे","ही हैं जैसे दूसरे हैं।"]],[3860,["जैसे कि आप मंदिरों में जाते हैं, वैसे ही हम यहाँ हैं,","बैठे हुए हैं - हमसे आपको छूने से क्या फ़ायदा है।"]],[3865,["चरणों में आने पर तभी फ़ायदा हो सकता है अगर","आपके अंदर वो कनेक्शन शुरू हो गया है।"]],[3871,["अगर हम इसके सामने बात कर रहे हैं और ये","कनेक्शन ही नहीं है तो इस बात करने से फ़ायदा?"]],[3877,["इसलिए किसी को भी पैर पे जाना और पैर","पे लेना, दोनों ही मैं दोष मैं समझतीं हूँ।"]],[3882,["क्योंकि लोग अब बहुत ज़बरदस्ती करेंगे। अगर","किसी से कहिए कि, \" भई हमारे पैर मत छुइए,\""]],[3887,["तो उनको तो लगता है माँ ने जैसे कुछ","उनको श्राप ही दे दिया।"]],[3889,["लेकिन मैं ये कहतीं हूँ, \"बेटे, तुम क्यों छू रहे हो ,","तुमको मैंने क्या दिया, किसलिए मेरे","पैर छू रहे हो?\""]],[3895,["जब तक तुमको कोई भी मैंने आत्मा का परिचय","दिया नहीं, तब तक आप मेरे पैर क्यों छू रहे हो,","मैं भी कोई ढोंगी हो सकतीं हूँ।"]],[3905,["मैं भी कोई गलत हो सकतीं हूँ। क्या वजह है","कि आप मेरे पैर छू रहे हैं, आदतन?"]],[3910,["और इस आदत की वजह से हमारा एकादश जो है","वो माथे पर हमारा बड़ा भारी एक चक्र होता है -"]],[3916,["जिसमें ग्यारह रूद्र बैठे हुए हैं - रूद्र आप","जानते हैं कि संहार शक्ति है"]],[3920,["अगर आप किसी और को इस तरह से गुरु मान लें,","तो इस तरफ में आपके रूद्र पकड़ जाते हैं।"]],[3927,["और जैसे ही पकड़ जाते हैं, ऐसे ही कैंसर","की बीमारी तो पहली चीज़ है।"]],[3935,["कोई आदमी भी, किसी भी आदमी,","समझिए एक पॉलिटिशियन है,"]],[3939,["किसी से सामने बहुत ज़्यादा झुकता है, वो भी","(अस्पष्ट) हो सकता है।"]],[3943,["एक अगर इकोनॉमिक्स वाला आदमी है या","बिज़नेस वाला आदमी है,"]],[3946,["वो अगर किसी के आगे ज़रुरत से ज़्यादा","नतमस्तक रहता है, अपने बिज़नेस के लिए, वो भी।"]],[3951,["कोई भी आदमी ज़रुरत से ज़्यादाअगर किसी के","सामने सिर झुकाये, तो उसको कैंसर की","बीमारी हो सकती है।"]],[3959,["उसके इधर की जो पाँच रूद्र में से,","पाँचों रूद्र पकड़ सकते हैं।"]],[3966,["इसलिए सब के सामने नतमस्तक होना, मनुष्य","के लिए बिलकुल व्यर्ज है।"]],[3974,["लेकिन किसी से अकड़ना भी वैसी ही बात है","कि, \"मैं ही गुरु हूँ, मैं ही भगवान हूँ।\""]],[3978,["\"मैं ही सब कुछ हूँ, मैं ही सब करता हूँ, मुझे कौन","बताने वाला है।\" ऐसे भी लोग हैं जो कहते हैं,"]],[3984,["\"कि तुम ही गुरु हो और तुम इस खोजो, दूसरों","को खोजने मत दो। तुम ही हो सब कुछ,\"","ये भी बात गलत है।"]],[3992,["क्योंकि आप खुद साक्षात्कारी नहीं हैं। जब तक","एक दीप जला नहीं, तब तक वो अपने आप","से जल नहीं सकता।"]],[4000,["एक जला हुआ दीप ही उसे जला सकता है।","पर उसमें लेना-देना कोई नहीं बनता है,"]],[4004,["उसमें किसी भी तरह का स्वार्थ नहीं होता है,","किसी भी तरह का उपकार नहीं होता है -"]],[4010,["ये तो आपका दीप जला नहीं, और एक दीप जला","हुआ है, उसे छू गया, आप जल गए।"]],[4016,["उसमें किसी भी तरह की ऐसी बात नहीं आती, कि","जिसमें आपको पूरी तरह से ये कहना है"]],[4022,["कि आपका कोई व्यक्तित्व ही न रह जाए - आप","एकदम से पागल जैसे उनके पीछे लगे रहे।"]],[4028,["अभी ऐसे बहुत से लोग मैंने देखे स्पेन","में पचास हज़ार लोग ऐसे हैं"]],[4032,["कि जो एक गुरु महाराज कोई हैं, उनके पीछे","में इतने नतमस्तक हैं, कि पागल हो गए।"]],[4037,["स्पेन की महारानी हमें मिलीं थीं, वो कहने लगीं,","\"भई आपके देश से ऐसे-ऐसे आप गुरु घंटाल","यहाँ भेजते हैं,"]],[4042,["कि उनका क्या करें कुछ समझ नहीं आता। हमारे","यहाँ पचास हज़ार यंग लोग एकदम पागल हो गए।\""]],[4050,["इस तरह के न जाने कितने तरह-तरह के","लोग आपने बाहर भेज दिए हैं।"]],[4055,["आपको एक्सपोर्ट के लिए और तो कुछ मिला नहीं","इस देश में कुछ बढ़िया से उठा-उठा कर के"]],[4060,["ऐसे लोगों को ऐसे लोगों को बाहर भेज दिया है","कि सबने नाक कटा के फेंक दी।"]],[4065,["और उनके लिए हम अगर कुछ कहें तो लोग कहते","हैं कि, 'माँ तो बहुत इन्टॉलरेंट हैं।'"]],[4069,["तो क्या ऐसे लोगों को हम हार पहनाएँ, उनकी","आरती उतारें, और उनको सिंहासन पे बिठाएँ।"]],[4077,["पहले ज़माने में तो दैत्यों को मारा जाता था।","मार के उनको पूर्ण तरह हत्या कर दी गई थी।"]],[4084,["लेकिन अब कमसकम उनको कहा तो जाए","कि ये दैत्य हैं और राक्षस हैं।"]],[4088,["उसमें आप लोगों को क्यों इतनी परेशानी हो जाती","है? क्या आप भी उन्हीं के साथ मिले हुए हैं?"]],[4094,["दूसरे लोगों को लूटना, खसोटना, उनसे पैसा लेना,","उनको दूसरे मार्ग में डालना ये कहाँ का धर्म है?"]],[4101,["और वो भी भारतीय हो कर के -","आपको क्या अधिकार है?"]],[4104,["ये एक तरह का अजीब सा छिपा हुआ","अग्रेशन (आक्रामकता) है।"]],[4112,["और ये इस तरह से छाया हुआ है, कि","आप आश्चर्यचकित होंगे, कि"]],[4117,["एक साहब वहाँ आते हैं लंदन और उन्होंने कहा","कि, \"साहब, मेरे लिए अगर आप रोल्स रॉयस","दें तो मैं आऊँगा।\""]],[4123,["अब सब लड़कों ने एक साल भर सिर्फ आलू खाया,","पैसा बचाया, और उनको रोल्स रॉयस दी।"]],[4128,["एक लामा साहब पहुँचे वहाँ - ये लोग आ कर","के मुझे बताते, मुझे बड़ी हैरानी हुई।"]],[4132,["लामा साहब, जो कि बड़े साधु-सन्यासी बनते हैं,","वो वहाँ पहुँचे, उन्होंने कहा,"]],[4137,["\"साहब, हमें तो मार्बल के फ्लोर फर्श के सिवा","होता नहीं\" - वहाँ मार्बल बड़ा मँहगा मिलता है,","स्वीडन में -"]],[4142,["तो स्वीडन के बेचारे लोगों ने भूखे रह कर के","मार्बल का फ्लोर बनाया, तो ये पधारे वहाँ"]],[4147,["और पधारने के बाद ये चीज़, कि आप उनके सामने","जाइए, तो एक हज़ार एक बार उनके सामने","आप झुकिए ।"]],[4153,["मैं आपको इसलिए ये सब बातें बता रहीं हूँ कि इस","सब चक्कर में कोई न कोई आप लोग होते ही हैं।"]],[4159,["सवेरे दस आदमी मिलने आये, उसमें से","नौ इस चक्कर के थे।"]],[4163,["मैंने पूछा, \"भई उनसे क्या मिलना था,","तुम क्या हीरा लेने गए थे?\""]],[4167,["अब आप बीमार हो, आपको हार्ट ट्रबल है, तो","अब आप उनके पास जाओ - कहने लगे,"]],[4171,["\"माँ, हमें समझ नहीं आता हमने तो कोई गलती","नहीं करी।\" मैंने कहा कि, \"तुम खोजने क्या","गए थे, ये बताओ।\""]],[4177,["जिसने परम की बात की, और जिसने परम दिया,","उसी के चरण में जाना चाहिए और उसी के","शरण में भी जाना चाहिए।"]],[4185,["बाकी सब बेकार है। इनकी बातें जो हैं - बातों","से तो इंसान का दिमाग खराब हो जाता है।"]],[4190,["आपने सुना होगा बहुत से लोग वेद पे बात","करते हैं - वेद, वेदाचार्य, ये, वो।"]],[4195,["एक महाशय बम्बई में हैं, बड़े भारी वेदाचार्य,","अमके पंडित, तमके पंडित - उनकी उमर","हमसे छोटी है, बड़ी नहीं।"]],[4201,["लेकिन वो जब बात करते हैं, तो ऐसा","लगता है कि सठिया गए।"]],[4204,["जो बकते चले जाते हैं, ऐसे बकते चले जाते हैं,","लोग तो उनके पास पाँच मिनट खड़ा","होना नहीं चाहते हैं।"]],[4209,["अब उनको समझ नहीं आता है कि","लोग उनसे भागते क्यों हैं।"]],[4212,["इस कदर क्रोधी और तप - तपस्वी क्या","कहना चाहिए - तापमय इंसान हैं"]],[4218,["कि जो भी उनके पास बैठता है वो कहता है, 'बाप","रे बाप, ये तो एकदम तूफ़ान आ जाता है।'"]],[4223,["और गुस्सा उनको इतना आता है, कि अगर","कोई उनकी बात किसी को समझ नहीं आई,"]],[4226,["तो कहते हैं, 'अरे तुम, तुम तो ऐसे दुष्ट हो,","तुम तो ऐसे खराब हो,' और ले कर के मारना","शुरू कर देते हैं ।"]],[4232,["अब बताइये, कितने वेदचार्य और फलाने और","ढिकाने होते हुए, उनके ये सारा बाहर ही रह गया -"]],[4238,["कुछ उनके ह्रदय में कुछ नहीं गया - न उनमें दया,","न अनुकम्पा, न कुछ नहीं - बस बड़बड़ाते रहते हैं","सुबह से शाम तक।"]],[4244,["ऐसे मैंने फ्राँस में बहुत से देखे। वो तो बस में","चढ़ते हुए बड़बड़ाते हैं। पूछा, \"क्या?\" ये कहने लगे","'बड़े भारी पादरी थे।'"]],[4250,["मैंने कहा, 'वाह भई! ये पादरियों का हाल है।'"]],[4254,["'ये एक बड़े भरी पादरी थे, इसलिए हम लोग","कुछ इनको कहते नहीं; बस में बड़बड़ाते चलते","हैं सुबह से शाम तक।'"]],[4260,["ऐसे बहुत मिलते हैं फ्राँस में। मेरे ख्याल से","वहाँ इस तरह के प्रकार बहुत हो चुके।"]],[4265,["लोगों ने बहुत अध्धयन-अध्धयन करके","और पगार लिया।"]],[4268,["तो इस तरह के गुरुओं के, जो कि सिर्फ बातचीत","ही बातचीत करते हैं"]],[4273,["आपको कहेंगे, 'पचास पारायण करो। दत्तात्रेय का","आप पारायण करो, गुरु का आप पारायण करो।'"]],[4278,["पचास पारायण करने के बाद में मिला क्या?"]],[4280,["एक महाशय हमारे पास आये, हमसे कहने लगे","कि, \"माँ, हमने तो चौदह वर्ष इनकी तपस्या करी।\""]],[4285,["मैंने कहा, \"अच्छा।\" \"और उन्होंने सिर्फ पारायण","करने को कहा और शिवजी का मंदिर","धोता रहा मैं।\""]],[4290,["\"और अब क्या हुआ?\" कहने लगे, \"एक मिनट","में कुण्डलिनी जागरण हो गया।\""]],[4295,["तो मैंने कहा, \" भई, ये सोचना चाहिए, कि","पारायण करने से परमात्मा मिलता है,"]],[4299,["तो अपने देश में कितने लोग हैं जो तो पढ़","भी नहीं सकते। इसका मतलब उनको","परमात्मा नहीं मिलेगा।"]],[4304,["सिर्फ पढ़े-लिखों को ही मिलेगा। जो","वेदाचार्य हैं, उनको मिलेगा।\""]],[4308,["जो वेद पढ़ सकते हैं - संस्कृत जानने वाले","कितने लोग हैं?"]],[4311,["मैं कहतीं हूँ कुरान-ए-शरीफ पढ़ने वाले कितने","लोग हैं, या बाइबिल पढ़ने वाले कितने लोग हैं?"]],[4316,["मतलब जो वो पढ़ते नहीं वो काम से गए।","ऐसे कैसे हो सकता है?"]],[4321,["जो परमात्मा सबका ही निर्माण करने वाला है,","सबको ही प्रेम करने वाला है, वो क्या","ऐसे काम करेगा?"]],[4329,["इसलिए जो गुरु तत्व में खराबी आ जाती है,","उससे आप लोग सब बच के रहिए।"]],[4333,["और ये गुरु तत्व हर तरह से आपके अंदर एक हट,","एक तरह की सीमा बाँध देता है।"]],[4340,["कि, 'ये हम करके दिखाएँगे।' उन्होंने कहा, 'चार","दिन का उपास,' 'हम दस दिन का","कर के दिखाएँगे।'"]],[4345,["ये सब चीज़ों से परमात्मा नहीं मिलता है।","सहज, सरल - 'सहज समाधि लगो।'"]],[4349,["सहज, सहज होना चाहिए। अगर जो चीज़ सहज","नहीं है, जिसमें असहज है, वो परमात्मा की चीज़","हो ही नहीं सकती है।"]],[4356,["एक सीधी बात आप सोचिए, कि आप इंसान बने,","आपने कौन सी मेहनत करी?"]],[4362,["आप क्या सिर के बल खड़े हुए, कि आपने अपनी","दुमें काटीं थीं, कि आप किस तरह से आप बन गए?"]],[4366,["आप इंसान अपने आप सहज सरल बन गए। इसी","प्रकार ऊँची स्थिति में जाने के लिए भी,","सहज ही भाव होना चाहिए।"]],[4373,["और जब तक सहज भाव नहीं आता है, तब तक","आप जो भी ऐसी ऊट-पटांग चीज़ें करते हैं,"]],[4379,["उससे आपको नुकसान होंगे, तकलीफें होंगी,","चक्र पकड़ेंगे। आपको परेशानी होगी,"]],[4385,["चाहे वो शारीरिक हो, मानसिक हो, बौद्धिक हो,","पर आप परेशानी में फँस जाएँगे।"]],[4389,["इसलिए मैंने पहले ही कहा कि सहज भाव से","बैठिए और कहा कि कबीर को पा लो,"]],[4393,["क्योंकि कबीर सहज भाव में थे। उनका मिलन","हो चुका था इसलिए वो मिलन में गाते थे।"]],[4399,["अब ये जो आपका जो चक्र है इसमें एक तरफ़ा तो","ये हुआ कि जहाँ आप किसी को भी गुरु मानते हैं।"]],[4409,["'ऐरा-गैरा, नत्थू-खैरा' जैसे कहते हैं,","किसी को भी गुरु मान लिया।"]],[4413,["गलत आदमी को गुरु मान लिया, गलत चीज़ों में","सिर झुका लिया। दूसरे ऐसे होते हैं कि जो","किसी को मानते ही नहीं।"]],[4421,["भगवान को भी नहीं मानते। \"मैं ही सब का गुरु हूँ।\"","उनसे इधर के जो पाँच रूद्र हैं वो पकड़ जाते हैं।"]],[4428,["इस प्रकार के दो प्रकृति के आदमी होते हैं।"]],[4432,["अब जो किसी को नहीं मानते हैं, जो बड़े","भारी वेदाभ्यास करने वाले हैं,"]],[4436,["इनके बारे में अभी मैंने आपको वर्णन कर","ही दिया है कि किस तरह के होते हैं।"]],[4440,["और उनकी जो प्रभुत्ति होती है, वो इस कदर","घनी-भूत तरीके से, घनी-भूत तरीके से","क्रोधी होती है,"]],[4450,["कि इस आदमी के पास भगवान हो ही सकता है,","ऐसा कोई भी नहीं विश्वास कर सकता है।"]],[4456,["भगवान इनके पास से गुज़र सकते हैं, ऐसा","भी कोई नहीं विश्वास कर सकता है।"]],[4460,["परमात्मा जो हैं वो प्रेम का, आनंद का, सौख्य का","और अनुकम्पा का सागर हैं। क्षमा का सागर हैं।"]],[4471,["जिस आदमी में इस कदर क्रोध, इस कदर सब के","साथ वितृष्णा हो, वो आदमी कभी भी परमात्मा","का आदमी हो नहीं सकता है।"]],[4485,["अब इसके बीच में जो विष्णु का तत्व है, इसके","बारे में ज़रूर में आपको बताना चाहूँगी"]],[4490,["क्योंकि अपने देश में हरेक जगह जाइए तो लोग","मुझसे ये कहते हैं, \"माँ हमारे गरीबी का","क्या होगा?\""]],[4495,["जैसे कि इन लोगों ने कुछ गरीबी का ठीक ही किया","हो, जो मुझसे कहते हैं कि गरीबी का क्या होगा।"]],[4503,["वही बात हुई। कृष्ण ने कहा कि, 'योगक्षेम","वाहमयम।' पहले योग को प्राप्त हो, उसके बाद","आपका मैं क्षेम करूँगा।"]],[4511,["जिस-जिस गावों में सहज योग हुआ, जहाँ-जहाँ","हम गए, जिन्होंने योग पाया, उनके सब प्रश्न","सॉल्व हो गए।"]],[4519,["किस प्रकार? सब से पहले तो सारी गन्दी आदतें","छूट जातीं हैं। धर्म जागृत हो जाता है।"]],[4525,["मनुष्य के अंदर की जितनी भी आदतें हैं, जिससे","मनुष्य जकड़ा हुआ है, वो सारी ही एक साथ","टूट जातीं हैं।"]],[4531,["आप जानते हैं, अभी बता रहे थे, कि दो सौ आदमी","हमारे साथ, परदेस से, घूम रहे थे।"]],[4536,["इन लोगों में से ना जाने कितने ड्रग लेते थे, कितने","अलकोहॉलिक्स थे, कितने कैसे-कैसे थे - हम","तो कुछ देखते नहीं।"]],[4543,["जो आया उसे पहले पार करा दो। पार होने","के बाद धर्म जागृत हो गया।"]],[4548,["एक महाशय थे उनको बहुत शराब पीते थे, कहने","लगे। फिर सहज योग में आते ही, दूसरे दिन","से उनकी शराब छूट गई।"]],[4555,["एकदम शराब छूट गई। तो उन्होंने कहा","कि अच्छा एक बार जर्मनी गए"]],[4559,["कहने लगे, 'थोड़ी देखें कैसा क्या,' उनको","एक शराब बहुत पसंद थी।"]],[4562,["पीते ही साथ कहने लगे ऐसीं उल्टियाँ हमें हुईं","और उसमें से ऐसी गन्दी बदबू आने लग गई"]],[4567,["कि हमने कहा कि, ' ये तो क्या हम मोलासिस","पी रहे हैं, कि क्या कॉर्क पी रहे हैं,"]],[4571,["कि समझ ही नहीं आ रहा था कि क्या पी रहे हैं?'","और 'उल्टी पे उल्टी, उल्टी पे उल्टी,"]],[4574,["उससे इतनी घृणा हो गई।' हमने तो कुछ नहीं","किया हम तो वहीं लंदन में बैठे हुए थे।"]],[4579,["लेकिन आप ही स्वयं धर्म हो जाने की वजह से,","क्योंकि आपके अंदर ये दस गुरु जागृत हो","जाते हैं, जो साक्षात धर्म हैं।"]],[4585,["इसकी वजह से अपने आप ही गन्दी आदतें","छूट गयीं। फिर उसके बाद,"]],[4591,["गन्दी आदतें छूटने के बाद में, आपकी दृष्टि","वहाँ जाने लग गई कि जिससे आपको","लक्ष्मी का योग हो।"]],[4598,["जैसे एक महाशय - आपको विश्वास इस बात का","भी होना ज़रा कठिन है लेकिन आपसे बताएँ,"]],[4603,["एक हमारे पहचान के थे, उन्होंने हमें बताया कि,","\"माँ, जब से मैं सहज योग करने लग गया,","बड़ा चमत्कार हो गया।\""]],[4611,["मैंने कहा, \"क्या हो गया?\" कहने लगे, \"जिस ज़मीन","पे मैं ऐसे ही टहलता था उसकी मिट्टी इतनी","बढ़िया हो गई"]],[4616,["कि एक आदमी आके मुझसे कहने लगा कि,","\"भई किसी फ़क़ीर ने आकर हमसे बताया"]],[4620,["कि, 'यहाँ की मिट्टी थोड़ी सी लेकर के तुम","अगर ईटें बनाओ तो पत्थर जैसी हो जायेंगीं।'"]],[4624,["\"तो वो हमारे यहाँ आया और हमसे तो वो","बिलकुल तौल के मिट्टी ले गया।\""]],[4632,["लेकिन पहले जागृति होनी चाहिए लक्ष्मी तत्व","की। लक्ष्मी तत्व की जागृति न किए बगैर"]],[4638,["अगर आप चाहें आपके अंदर लक्ष्मी आएगी,","तो नहीं - पैसा आ जायेगा।"]],[4641,["पैसा आ जाएगा, लक्ष्मीजी नहीं आयेंगी।","और लक्ष्मीजी कैसी होतीं हैं?"]],[4646,["एक हाथ से उनके दान है, एक हाथ से उनका","आश्रय है, और हाथ में दो कमल के सुन्दर पुष्प हैं"]],[4652,["जो कि उनके प्रेम के प्रतीक हैं। और इतना ही","नहीं, पर एक भौंरा जिसके अंदर इतने काँटे हैं,"]],[4659,["उसे तक वो अपने अंदर समां लेतीं हैं।","ऐसे लक्ष्मीपति आप हो सकते हैं,"]],[4664,["जो समाधान में इतने संतुलन में खड़ीं,","कि कमल पर पे खड़ीं रहतीं हैं।"]],[4669,["इतनी सादगी से, इतनी डिग्निटी से वो रहतीं हैं -"]],[4672,["मैं तो बहुत आजकल देखतीं हूँ कि जो पैसेवाले","हैं, उनके अंदर कोई डिग्निटी ही नहीं।"]],[4678,["उनके अंदर दिखाई ही नहीं देता है कि","इनके अंदर कोई प्रतिष्ठा हो।"]],[4683,["बिलकुल अप्रतिष्ठित तरीके से इस तरह से","लांगूरचाल्या करते हैं कि समझ में नहीं आता है"]],[4688,["कि इतनी चापलूसी करने की इनको क्या ज़रुरत","है जब इनके पास लक्ष्मी का प्रसाद है।"]],[4693,["पर लक्ष्मी का प्रसाद नहीं है, सिर्फ पैसा है। अगर","गधे के ऊपर आप अगर नोट लगा दीजिए, तो","क्या वो लक्ष्मीपति बन जायेगा?"]],[4701,["तो ऐसे पैसेवाले से वो लक्ष्मीपति जो कि","अपने शान में, अपने गौरव में खड़े रहते हैं,"]],[4709,["जो किसी के सामने हाथ नहीं फैलाते हैं","- जब हैं तब बाँटते ही रहते हैं।"]],[4713,["ऐसे हमने अपनी आँखों से लोग देखे हुए हैं,","ऐसे हमने जाने हैं लोग जो होते हैं।"]],[4717,["हमारे स्वयं पिता इस तरह के थे। उनकी इतनी","दानी प्रवृत्ति थी - वो सवेरे ख़ासकर इतवार","को चीज़ें बाँटा करते थे।"]],[4724,["किसी दिन कम्बल बाँट दिया किसी दिन कुछ।","और उनकी आँख हमेशा नीचे रहती थी और","देते रहते थे, देते रहते थे।"]],[4732,["लोग दो-दो ले जाएँ, कोई तीन-तीन ले जाएँ। तो","वहाँ कोई कहे उनसे, 'क्या कर रहे हैं आप?'"]],[4736,["'आप दो-दो, तीन-तीन कम्बल एक आदमी","को दे रहे हैं, आँख क्यों नीचे किये हैं?'"]],[4740,["कहने लगे, \"भई मैं दे नहीं रहा हूँ, दे कोई और रहा","है, इसलिए मेरी शर्म लगती है। सब लोग कहते","हैं कि, 'आप दे रहे हैं,' ऐसी बात है।\""]],[4745,["ऐसे तो बड़े स्वातंत्र वीर थे लेकिन इस","मामले में उन्हें शरम लगती थी।"]],[4749,["कि, \"लोग मुझसे कह रहे हैं, मुझे बड़ी लज्जा आती","है। लोग मुझे कह रहे हैं कि, 'तुम दे रहे हो।'\""]],[4753,["और देते वक्त में कहने लगे, 'अब देने वाला जो वो","जाने, मुझे मतलब नहीं। दे दो, चाहे चार दे,","मुझसे क्या मतलब?"]],[4759,["'जो दे रहा है वो जाने, मुझे क्या करने का,","मैं तो बीच में खड़ा हुआ हूँ।' ऐसे लोग थे","पहले इस भारतवर्ष में।"]],[4766,["अब तो पता नहीं कुछ वो दिखाई ही नहीं दे","रहा इस तरह का तरीका।"]],[4770,["पैसे वाले का तो मतलब यही हो गया कि बहुत","घमंडी, बहुत क्रूर और किसी का परवाह नहीं।"]],[4777,["अपने माँ-बाप की परवाह नहीं, अपने भाई-बहनों","की परवाह नहीं, अपने को बहुत सब कुछ समझना"]],[4782,["- ये पैसे वाले के लक्षण हैं। दुनिया में किसी","की भी परवाह नहीं करना।"]],[4788,["ये जो हमारे यहाँ अब नया तरीके का","पैसे का भूत सवार हो गया है,"]],[4793,["इस भूत से हमारी जो समाज व्यवस्था","है, पूरी तरह से टूट जाएगी।"]],[4796,["औरतों के लिए भी अब ये हो गया है","कि पति से बढ़कर पैसा हो गया है।"]],[4801,["बच्चों से बढ़कर पैसा हो गया है।","हर चीज़ में पैसा आ गया है।"]],[4804,["जहाँ पैसा मुख्य हो जाता है और प्रेम नगण्य","हो जाता है वहाँ लक्ष्मी का स्वरुप ख़तम।"]],[4811,["वहाँ सब लक्ष्मी का स्वरुप ख़त्म हो जाता है","और उस जगह सिर्फ पैसे का एक एकदम"]],[4818,["रूखा जीवन आ जाता है, जो आज आपको","परदेस में दिखाई देता है।"]],[4822,["यहाँ से भी जो हिंदुस्तानी परदेस में जाते हैं,","उनकी पता नहीं क्या हो जाती है"]],[4825,["सारी परंपरा टूट कर के वो बेतहाशा","पैसे की तरफ दौड़ रहे हैं।"]],[4829,["मैं तो उन लोगों को देखकर हैरान होती हूँ","कि ये क्या मेरे ही देश के लोग हैं।"]],[4834,["इस तरह से जब हम अपने को गलत रास्ते पर डाल","देते हैं, तब उसपे बहुत ज़ोर का मारा होता है।"]],[4842,["ऐसे पैसे वालों को बहुत बुरे दिन भी देखने पड़ते हैं।"]],[4845,["उनके बच्चे जो वाहियाद निकल जाते हैं, इधर","-उधर दौड़ जाते हैं, और गलत काम करते हैं।"]],[4849,["ऐसे पैसे वालों के लिए कोई भी आशीर्वाद","नहीं होता है।"]],[4853,["आप जा के देखिए रात-रात भर सोते नहीं -","उनको परेशानियाँ रहतीं हैं।"]],[4857,["तो जो पैसा लक्ष्मी स्वरुप है, उस पैसे को","आप प्राप्त करते हैं। उस संपत्ति को, उस धन को"]],[4864,["आप प्राप्त करते हैं, जो लक्ष्मी की देन है, जब","आपके अंदर कुण्डलिनी जागृत होती है।"]],[4869,["और इसलिए इस देश का जो दारिद्रय है, उसी दिन","दूर होगा जब यहाँ पर लोग योग को प्राप्त होंगे।"]],[4875,["उससे पहले कभी नहीं हो सकता है -","आप कोशिश कर लीजिये।"]],[4878,["मैं गई थी वहाँ पर, राहुरी में मैंने देखा","कि खूब झोपड़ियाँ बनी हुईं हैं।"]],[4881,["कहने लगे, \"अब ये झोपड़ियाँ बनाईं हैं।\"","मैंने कहा, \"अच्छा, कि कोई नगर बनाया है इनने।\""]],[4885,["मैंने कहा, \"ये नगर कैसा है, पता नहीं?\"","वहाँ से जा रहे थे, तो सामने रास्ते पर,","जिस रास्ते से जा रहे थे"]],[4890,["सामने इस तरह से रास्ता था। उसमें से लोग खूब","शराब पी-पी कर के आकर सामने रस्ते पर","धड़ा-धड़ गिर रहे थे।"]],[4896,["एक तो हमारे मोटर के सामने गिर गया। और एक","नहीं, दो नहीं, काफी सारे लोग वहाँ से निकले","जा रहे हैं।"]],[4902,["मैंने कहा, \"भई, ये कौन सा नगर बनाया? ये क्या ये","झोपड़ियों का नगर बनाया इसमें सब शराब","ही चलती है?\""]],[4907,["कहने लगे, \"हाँ, ये तो ऐसे ही नगर बना है।\""]],[4909,["इनको झोपडी दी तो उसमें शराब शुरू कर दी। सौ","रुपया दे दिया तो उसमें शराब शुरू कर दी।"]],[4913,["ये कोई गरीबी हटाने का लक्षण नहीं है।","इस तरह से गरीबी नहीं हटेगी।"]],[4918,["ये तो शराब ऐसे पीछे पड़ गई कि इसमें से पचास","फ़ीसदी गरीब मर ही जाएंगे तो गरीबी","हट ही जाएगी।"]],[4925,["इलाज़ तो ऐसा ही हो रहा है कि लोग","जीने ही नहीं वाले हैं।"]],[4928,["रास्ते पर धड़-धड़ गिर रहे थे - उनमें कोई","ताकत नहीं थी।"]],[4931,["क्षीण-हीन ऐसे मरे हुए लोग - इनकी गरीबी","आप क्या हटा सकते हैं?"]],[4936,["इनको तो पैसा मुफत देने से, इन्होंने शराब पी-पी","कर के, और और धंधे कर-कर के, और अपना","सर्व सत्यानाश कर लेना है।"]],[4945,["अब गरीबी हटाने पर एक और प्रश्न है","कि जब हम इस तरह की तांत्रिक विद्या"]],[4951,["और ऐसी मैली विद्याएँ करते हैं, तो लक्ष्मीजी","दूसरे पैर से चली जातीं हैं।"]],[4955,["जिस घर में तांत्रिक विद्या शुरू हो जाएगी,","लक्ष्मीजी दूसरे पैर से चलीं जायेंगीं।"]],[4959,["आज मैं विशेषकर धर्म पे बात कर रहीं हूँ क्योंकि","ये बहुत जानना ज़रूरी है कि हम धर्म में","कितनी गलतियाँ करते हैं।"]],[4966,["जो लोग अपने घर में दिवाली मानते हैं,","हर जगह दीप जला देते हैं।"]],[4971,["रात को कि बाहर (अस्पष्ट) होती है उस वक़्त","ये न हो कि लक्ष्मी कहीं लौट के चलीं जाएँ -","उनको अँधेरा पसंद नहीं।"]],[4976,["और जितनी मैली विद्या है, जितनी भूत विद्या,","प्रेत विद्या, शमशान विद्या,"]],[4981,["और ये दुष्ट गुरुओं का जो चक्कर चला है, अगुरु","लोग जो हैं, इन्होंने जो चक्कर चलाए हुए हैं,"]],[4987,["इन सब चक्करों की वजह से अपने देश में","बिलकुल कालिख पुत गई है।"]],[4992,["एकदम काला अंधकार फ़ैल गया है और वो काला","अंधकार होने की वजह से अपना देश","उठ नहीं पाता है।"]],[5000,["जब तक इन लोगों को आप समुद्र में नहीं डाल","दीजिएगा, जब तक इनको आप अपने ह्रदय","से निकाल नहीं दीजिएगा,"]],[5006,["और इस तरह की चीज़ें जब तक","आपके समाज से जाएँगीं नहीं,"]],[5009,["आपके समाज की गरीबी कभी हट नहीं सकती","क्योंकि लक्ष्मीजी ऐसे स्थान में बसतीं नहीं।"]],[5015,["तीसरी चीज़ जिसलिए लक्ष्मीजी हमारे देश में नहीं","हैं, उसका मुख्य कारण ये है कि, 'यत्र नार्या","पूज्यन्ते तत्र रमन्ते देवता'।"]],[5023,["माने ये, कि जो इंसान स्त्री की पूजा करता है,","स्त्री को मानता है, उसकी इज़्ज़त करता है,","वहाँ देवता का रमण होता है।"]],[5034,["लेकिन स्त्री भी पूजनीय होनी चाहिए। स्त्री","भी ऐसी हो कि जिसकी पूजा न की जाए,","तो ऐसी स्त्री से फायदा क्या?"]],[5041,["तो स्त्री ऐसी होनी चाहिए जो पूजनी जाए, पूजी जाए,","जो पूजनीय हो, जो पवित्र हो, जो उच्च विचार","लेकर के संसार में रहे,"]],[5050,["प्रेम से अपने घर, और रिश्तेदार","और सबको को संभाल के रखे -"]],[5054,["ऐसी जो स्त्री हो जो पूजी जाए, ऐसी स्त्री के पति जो","हों, उनकी इज़्ज़त करें, घरवाले उनकी इज़्ज़त करें,"]],[5062,["स्त्री की, बच्चों की, लड़कियों की, माँ की, जहाँ","इज़्ज़त होती है, वहाँ देवता रमण करते हैं, नहीं","तो भूतों का नाच शुरू हो जाता है।"]],[5072,["अब आप सुन रहे हैं कि अपने देश में स्त्री की","क्या स्तिथि है। मैं तो तब भी कहूँगी, कि","हिंदुस्तान की नारी"]],[5078,["एक विशेष स्वरुप की औरत है जिसने","बहुत कुछ सहन किया है।"]],[5081,["पुरुषों की ज़्यादती जितनी हिंदुस्तानी नारी","सहन करती है, वो कोई नहीं ऐसा करता है।"]],[5086,["और हमारा समाज ही पूरा ऐसा बन गया है आज,","कि बिलकुल हम लोग इस मामले में","निर्लज्जता से बात करते हैं।"]],[5092,["कोई कहता है कि, 'साहब इतने लाखों रुपया","की डॉउरी दीजिए और नहीं तो आप हमारे","दरवाजे नहीं आइये।'"]],[5098,["बिल्कुल उनको इस मामले में शर्म भी नहीं","आती है इस तरह की बात करने की।"]],[5102,["और इस तरह की चीज़ें इतनी अपने समाज","में आज प्रचलित हो रहीं हैं।"]],[5106,["जितनी-जितनी ये बढ़तीं जाएँगीं उतनी-उतनी","आपके समाज में गरीबी आएगी।"]],[5109,["किसी लड़के को बेच कर के और लड़की के नाम","पे अगर आपने रुपया इकठ्ठा किया,"]],[5114,["आप देख लीजिए अगर उसमें कभी भी आपको","यश नहीं आएगा। आप कर के देख लीजिए।"]],[5118,["कोई आदमी है लाखों रुपया इस तरह से ले ले,","उसको कोई न कोई घाटा आएगा, कोई न","कोई बड़ी बर्बादी होगी,"]],[5123,["और जा कर के वो बिल्कुल ऐसी दशा में पहुँच","जायेगा जहाँ से निकल नहीं पायेगा।"]],[5127,["या तो कोई ऐसे बीमारी में फँस जायेगा,","या ऐसे कोई बेकारी में फँस जायेगा -"]],[5132,["कोई न कोई ऐसी चीज़ उसे हो जाएगी कि","जिससे वो पछताना पड़ेगा।"]],[5136,["क्योंकि किसी भी सती स्त्री किसी भी स्त्री जाति","का अपमान करना शक्ति का अपमान है।"]],[5141,["अगर वो स्त्री, हाँ, इस तरह की है, जो बेकार है और","जो पूजनीय नहीं है उसके बारे में मैं नहीं कह रही।"]],[5148,["पर अपने भारतवर्ष में आज भी, मैं ज़रूर कहूँगी,","कि यहाँ की स्त्री बहुत पूजनीय है।"]],[5153,["अब भी औरतें हमारे यहाँ ग्लैमर वगैरा में विश्वास","नहीं करतीं हैं। अब हैं कुछ पागल उनको छोड़िए।"]],[5158,["लेकिन अधिकतर औरतें सादगी से अपने","चरित्र को सँभालते हुए रहतीं हैं।"]],[5162,["जिस देश में पद्मिनी जैसे लोगों ने जौहार","किया - कोई विश्वास नहीं करता है।"]],[5166,["अगर परदेस में जा कर मैं कहूँ कि, \"हमारे देश में","तो चेस्टिटी के पीछे में औरतों ने जौहार कर","लिए, तुम बात क्या करते हो?\""]],[5172,["वो कहने लगे, \"हो ही नहीं सकता है।\" तो मैंने कहा","कि, \"तुम क्या समझोगे?"]],[5175,["तुम उस ऊँची चीज़ को तुमने जाना नहीं,","उन आदर्शों को तुमने जाना नहीं।\""]],[5180,["आज उन/उस आदर्शों को सब को मटियामेट कर","के और हम इन पागलों के पीछे में अगर भागना","शुरू कर दें,"]],[5185,["तो मैं आपसे बता रहीं हूँ, गरीबी जो नहीं आनी","थी वो आ जाएगी - और इन लोगों में क्या","कम गरीबी है?"]],[5191,["आप इनको समझते हैं रईस हैं, मैं तो सोचतीं हूँ,","इनसे गरीब कोई नहीं।"]],[5195,["इनके अगर घर जाइये अगर एक कप इन्होंने चाय","दिया तो इनका दिल जो है बैठ जायेगा।"]],[5199,["एक कप चाय अगर इनके घर से खर्च हो गया,","तो इनका दिल बैठ जाता है। और हम","लोग दिलदार हैं।"]],[5206,["गरीब भी हैं, तो भी हमारे घर में कोई आता है","तो उसको चाय, पानी, कुछ न कुछ।"]],[5211,["कुछ नहीं है, तो उसको गुड़ ही खाने को दे देंगे","भैया - जो भी घर में है। जो कुछ भी ह्रदय से","निकाल कर के।"]],[5216,["हमारे साथ जो लोग सफर कर रहे थे देहातों में,","हैरान थे कि, 'ये लोग झोपड़ियों में रहते हैं और","इनका दिल है कि राजा जैसे।'"]],[5223,["और ये लोग महलों में रहते हैं और ये हैं","बिल्कुल भिखारी।"]],[5226,["मैं तो रोज़ के अनुभव लंदन में देखतीं हूँ, कि जितने","भी विदेशी लोग हैं, बड़ी-बड़ी पोज़िशन में हैं,","बड़ी-बड़ी इसमें हैं"]],[5232,["आप उनको कितने भी प्रेजेंट दे दीजिए, कुछ भी","कर दीजिए, उनसे एक पैसा नहीं निकलने वाला।"]],[5237,["हमारे साहब की सेक्रेटरी है, वो साहब से कहती है","कि, \"भई आपके बच्चे आ रहे हैं, ग्रैंड चिल्ड्रन,","तो आप परेशान नहीं हैं?\""]],[5245,["उन्होंने कहा, 'क्यों भई?' मुझसे कहती,","'आप परशान हैं?' मैंने कहा, 'क्यों?'"]],[5248,["कहने लगी, 'आपका सारा घर गन्दा हो जायेगा।'","मैंने कहा, \"ये घर किसके लिए है?"]],[5251,["ये क्या मेरे लिए घर है? ये तो उन्हीं के लिए","घर है जो मेरे बच्चे आयें।\""]],[5255,["उनका ये था कहतीं हैं कि, \"हमारी जो ग्रैंड","मदर थीं, जब तक दो पी हमसे नहीं लेतीं थीं,","हमको टेलीफोन नहीं करने देतीं थीं।\""]],[5262,["और उसी लंदन शहर में, आप आश्चर्य करेंगे,","कि दो बच्चे हर हफ्ते में मारे जाते हैं।"]],[5269,["तो ऐसे देश के एफ्लुएन्स से भगवन बचाये रखे","- आप लोग उस ओर जाने की कोशिश न करें।"]],[5274,["जो कुछ है उसमें समाधान से, परमात्मा की ओर","दृष्टि दे कर के, अपने लक्ष्मी तत्व को","आप जागृत करें।"]],[5281,["इस देश का लक्ष्मी तत्व बिल्कुल जागृत हो","सकता है, पर उसका सौष्ठव और उसका","गौरव समझते हुए।"]],[5287,["अगर हम उसको न समझें और व्यर्थ की चेष्टाओं","से और हम चाहें कि लक्ष्मी इकठ्ठा कर लें,"]],[5294,["तो कभी भी हमारे अंदर लक्ष्मी तत्व जागृत नहीं हो","सकता है। यही अपने देश का तरुणोपाय है","कि अपने धर्म में जागृत हो।"]],[5303,["ये हमारे देश के लिए एक ही तरीका है, इतना ही,","लेकिन जब ऐसा होगा, और होगा ही क्यों न होगा"]],[5311,["उस वक़्त सारे दुनिया के देश आपके चरणों में","लोटेंगे और जानेंगे कि असली श्रीवंति जो है,","असली रियासत जो है, वो इस देश में है।"]],[5323,["अब भी लोग देखते हैं तो आँखें खुल जातीं हैं,","कहते हैं कि, 'ये इतने गरीब लोग"]],[5327,["साफ़ लोटा माँज कर के, उसमें दूध ले कर","के आ गए हमें देने के लिए।'"]],[5331,["ये लोग विश्वास नहीं कर सकते हैं कि इतने बड़े","ह्रदय के लोग इनके देहातों में कैसे हैं।"]],[5337,["सो उस चीज़ को खोना नहीं है। और ये समय","ऐसा आया है कि हम खो रहे हैं, हमारे","बच्चे बिगड़ रहे हैं।"]],[5343,["और इस ओर हम जा रहे हैं। इस वक़्त बहुत","ज़रूरी है कि सहज योग की स्थापना कर के"]],[5348,["और अपने बच्चों को रोक लीजिए। उनके अंदर","लक्ष्मी तत्व जागृत कर के उनके अंदर ये","गौरव भर दीजिए।"]],[5354,["आज मैंने आपसे विशेषकर के लक्ष्मी तत्व पे","बात की है क्योंकि बहुत ज़रूरी चीज़ है -"]],[5359,["आप लोग जाने कि हमारा देश गरीब क्यों है।"]],[5362,["और इसकी गरीबी आप गरीबों को रुपया देने से","नहीं होगी - आप दे कर देखिए।"]],[5367,["आप किसी भी गरीब आदमी को सौ रुपया दीजिए","- न वो गुत्ते पर गया तो कहाँ आप जाएँगे।"]],[5371,["कोई भलाई नहीं। इसलिए आप जान लीजिए कि","पैसे के झेलने के लिए भी लक्ष्मी तत्व ज़रूरी है।"]],[5377,["ऐसे ही रईस लोगों को भी सोचना चाहिए कि पैसा","जो है, वो हमारे लिए परमात्मा ने दान के","लिए दिया है।"]],[5383,["हम बीच में एक माध्यम बने खड़े हुए हैं","और इसे दान के लिए दिया हुआ है।"]],[5387,["इसका जो कुछ उपकर्म हो सकता है","हम करना चाहते हैं।"]],[5390,["और इससे जो भी लोगों की मदद हो सकती है","वो करना चाहिए और अच्छे मार्ग में, संमार्ग","में रहना चाहिए।"]],[5396,["अच्छे काम करना चाहिए। सबसे बड़ी चीज़ है","परमात्मा का आशीष।"]],[5400,["जब तक उसका आशीष नहीं मिलेगा, सब चीज़","व्यर्थ है। उसमें कोई शोभा ही नहीं है।"]],[5404,["ऐसे घर में जाओ तो आपकी टांगें टूटने लग","जातीं हैं। आपको लगता है, बाबा कब","भागते हैं इस घर से।"]],[5408,["उनका खाना खाओ तो आपको उल्टी हो जाएगी।","कोई न कोई तकलीफ हो जाएगी।"]],[5412,["ऐसे लोग जो बिल्कुल ही पैसे से जुटे हुए हैं एक","मशीन बन जातें हैं। उनके अंदर कोई ह्रदय नहीं।"]],[5418,["क्या अपने घर में लोग सोचते हैं, 'हमारे घर में कुछ","भी नहीं हो, हम भूखे रह लेंगे, पर ऐसे लोगों","के घर का खाना नहीं चाहिए।'"]],[5425,["मनुष्य को ये जान लेना चाहिए कि हमारे अंदर","परमात्मा ने स्वयं साक्षात् लक्ष्मी का स्थान","रखा हुआ है,"]],[5431,["वो हमारे अंदर बसीं हुईं हैं, सिर्फ उनको","जागृत मात्र करना है।"]],[5435,["और उस जागृति के लिए आपको कोई बुद्धि","के घोड़े दौड़ाने की ज़रुरत नहीं,"]],[5438,["कोई विशेष सोचने की ज़रुरत नहीं, सिर्फ","कुण्डलिनी का जागरण होते ही ये","कार्य हो सकता है।"]],[5442,["तो इसे क्यों न करें और इसे करना","नितांत आवश्यक है।"]],[5446,["और ये होने का समय आ गया है। एक विशेष","चीज़ है कि ये विशेष समय आ गया है,"]],[5451,["और इस विशेष समय पर आप इस वक्त उपस्थित","हैं। इसका आप पूरी तरह से उपयोग करें और","अपने लक्ष्मी तत्व पहले जागृत कर लें।"]],[5459,["आज के लिए इतना ही काफी है, फिर और दो दिन","लेक्चर दूँगी तब उस पर और तत्वों के बारे में","आपको बताऊँगी।"]],[5465,["आज अब थोड़ा सा हम लोग रिअलीज़ेशन","का प्रोग्राम करेंगे।"]],[5469,["आपको कोई अगर प्रश्न हो तो आप चिट्ठी लिख कर","के मुझे दे दें - मैं उसके जवाब थोड़ी देर","के लिए दे दूँगी।"]],[5516,["प्रश्न: परेशान और अशांत मन किसी भी ध्यान","पर ध्यान केंद्रित करने में असमर्थ हूँ।"]],[5521,["(अस्पष्ट) और सहज योग की तकनीक को समझना","चाहता हूँ लेकिन मुझे पूर्ण मार्गदर्शन की","आवश्यकता है।"]],[5528,["क्या मुझे परमपूज्य माताजी आपका मार्गदर्शन","प्राप्त हो सकता है ताकि मैं इसकी विधि/अभ्यास","को पूरी तरह से समझ सकूँ?"]],[5535,["श्री माताजी: अब, आपकी जानकारी के लिए हमारा","पहले से ही एक छोटा केंद्र है और आप इसका","पता योगी महाजन से ले सकते हैं।"]],[5544,["हमारे साथ डॉक्टर भी हैं जो मरीजों की देखभाल","कर रहे हैं। आपको उनके साथ अपनी","अपॉइंटमेंट लेनी चाहिए"]],[5551,["और जाकर उनसे मिलना चाहिए और वे आपकी","यथासंभव मदद करने की कोशिश करेंगे और","मुझे यकीन है कि यह काम करेगा।"]],[5561,["प्रश्न: यह कैसे देखा जाए कि कुंडलिनी जागृत हो","गई है? जब कुंडलिनी जागृत हो जाती है तो","उसका प्रभाव/असर क्या होता है?"]],[5570,["श्री माताजी: वास्तव में जब कुंडलिनी ऊपर उठती","है, तो खट्ट से बहार निकलती है उन लोगों","में जिनमें कोई रुकावट नहीं होती।"]],[5578,["यदि कोई शारीरिक, मानसिक, भावनात्मक या फिर","आध्यात्मिक बाधा हो तो वह रुक जाती है।"]],[5584,["आप जागृति को इस प्रकार महसूस कर सकते हैं,","कि वह स्पंदित हो रही है लेकिन ऊपर की","ओर नहीं बढ़ रही है।"]],[5590,["तो जब ईसा मसीह (अस्पष्ट) जैसे वो कहते हैं,","'बस एक सेकंड के अंतराल में - तत्क्षण'"]],[5597,["तत्क्षण में; लेकिन हर किसी के मामले में यह","उसी गति से नहीं चलती है। तो तत्क्षण जागरण","के परिणामस्वरूप क्या होता है,"]],[5607,["कि आप अपने सिर से ठंडी हवा और अपने हाथों","से ठंडी हवा को महसूस करना शुरू कर देते हैं"]],[5613,["- आप अपने आसपास ठंडी हवा को महसूस","करना शुरू कर देते हैं।"]],[5616,["यह पहली चीज़ है जो घटित होती है। लेकिन","अगर यह पूरी तरह से जागृत नहीं हुई है,"]],[5620,["एक बिंदु पर रुक गई है, तो क्या होगा? तो फिर","इसे इस बिंदु को, इस आज्ञा चक्र को ही पार","करना होगा जो कि मैं आपको कल बताऊँगी।"]],[5632,["तब, तब आप निर्विचार हो जाते हैं, आप विचारहीन","हो जाते हैं लेकिन चैतन्य (अस्पष्ट - लुप्त)","हो जाता है,"]],[5638,["उसका बहना बंद हो जाता है - आपको चैतन्य","महसूस नहीं होता, आपको ठंडी हवा","महसूस नहीं होती।"]],[5642,["स्पन्द का मतलब है ठंडी हवा, आपको सिर पर","महसूस नहीं होती, आपको कहीं भी","महसूस नहीं होती।"]],[5646,["यह तो रुक जाएगी लेकिन आप विचारशून्य","हो जायेंगे।"]],[5648,["अब जब यह यहाँ रुकती है, विशुद्धि चक्र पर,","तब आपको निर्विचार जागरूकता/समाधि","महसूस नहीं होती है,"]],[5655,["आपको चैतन्य महसूस नहीं होता है लेकिन","आप कुछ और महसूस करते हैं, बेहतर है,"]],[5660,["आप शांत हो जाते हैं और आप साक्षी","बनना शुरू कर देते हैं।"]],[5662,["इसलिए, जब हममें रुकावट होती है तो","अलग-अलग प्रभाव हम महसूस करते हैं।"]],[5667,["लेकिन अगर हममें कोई रुकावट नहीं होगी","तो फ़ौरन जागृत हो जाएगी।"]],[5676,["प्रश्न: क्या आत्मा शरीर के गर्भ में बाहर से प्रवेश","करती है या गर्भ में ही निर्मित होती है?"]],[5685,["श्री माताजी: यह बाहर से प्रवेश करता है।"]],[5687,["प्रश्न: कृपया स्पष्ट करें कि क्या सिद्ध योग","और सहज योग एक ही है।"]],[5692,["यदि ऐसा है तो 'ओम नमो शिवाय' जैसे मंत्रों","का जाप और कुंडलिनी जागरण।"]],[5699,["श्री माताजी: सिद्ध योग तथा कुंडलिनी जागरण या","कुंडलिनी (अस्पष्ट) एक ही/समान हैं - इसमें","कोई संदेह नहीं है।"]],[5707,["लेकिन आप सिद्ध नहीं हैं। सिद्ध बनने के लिए","आपको अपनी कुंडलिनी जागृति प्राप्त","करनी होगी।"]],[5712,["जब आपको अपनी कुंडलिनी जागृति मिल जाए,","तो आपको स्वयं को स्थापित करना होगा,"]],[5716,["ताकि आप सिद्ध हो जाएँ - आप साबित करते हैं।"]],[5718,["सिद्धयोग कोई ऐसा शब्द नहीं है, कोई काल्पनिक","बात नहीं है कि हम किसी को कहते रहें।"]],[5723,["अब यदि आप बिना आत्मसाक्षात्कार के शिव","का मन्त्र कहते हैं,"]],[5727,["तो आपको हृदय संबंधी परेशानी हो जाएगी,","क्योंकि हृदय में शिव का वास है"]],[5732,["और यदि आप शिव का नाम ऐसे ही लेते हैं,","अंधाधुंध, तो वह आपसे नाराज़ हो जाते हैं, और","आपको हृदय रोग हो सकता है।"]],[5740,["तो, सबसे पहले आपको अपना आत्मसाक्षात्कार","प्राप्त करना होगा, आपको अपनी सिद्धता","प्राप्त करनी होगी।"]],[5746,["जब आप जुड़े/एकरुप होते हैं, तो आपको पता","होता है कि मंत्र कब बोलना है। सिर्फ अंधाधुंध","तरीके से कोई एक या दूसरा नाम लेना नहीं।"]],[5758,["किसे कौन सा नाम लेना है, यह आपकी","कुंडलिनी द्वारा तय किया जाना है।"]],[5763,["वह आपको बताती है, वह आपको बताती है","कि आपको कौन सा मंत्र बोलना है,"]],[5767,["कौन सा शब्द जपना है, कुंडलिनी कहाँ है।","वह ही आपका मार्गदर्शन करती है।"]],[5782,["प्रश्न: सामान्य व्यक्ति कैसे जाने कि विशेष","व्यक्ति की कुण्डलिनी जागृत है?"]],[5789,["श्री माताजी: सामान्य ही असामान्य होते हैं।","सामान्य असामान्य लगते/दिखते हैं।"]],[5793,["असामान्य जो दिखते हैं वो सामान्य होते हैं।","क्योंकि उनका चित्त, असामान्य का चित्त","जो है, वो सामान्य में नहीं फँसता है।"]],[5805,["जिसको हम सामान्य समझते हैं, हमारा चित्त वो","असामान्य है,"]],[5809,["क्योंकि उसके अंदर जो असामान्य है, उसके अंदर","पहुँचा ही नहीं - वो 'जैसे कि तैसी रख दीन्हि","चदरिया'।"]],[5817,["'(अस्पष्ट) गुरु, ऋषि मुनि जन ओढ़ी,","ओढ़ी कि मैली कीन्हि चदरिया,"]],[5824,["दास कबीर जतन से ओढ़ी,","जैसी की तैसी रख दीन्हि चदरिया।'"]],[5830,["मतलब, साधारण लोग, जो साधारण दिखते हैं,","वे अपनी असाधारणता बरकरार रखते हैं,"]],[5836,["जबकि तथाकथित सफल असाधारण लोग, अपनी","असाधारणता समाप्त कर चुके होते हैं"]],[5843,["और साधारण ही बने रहते हैं - उनका","ध्यान सामान्य चीजों पर रहता है।"]],[5854,["प्रश्न: मैं आपको गुरु मानता हूँ क्योंकि आप","मुझसे श्रेष्ठ हैं। पर आपका कहना है कि","गुरु नहीं होना चाहिए।"]],[5862,["श्री माताजी: हाँ! मैं तो माँ हूँ, भई मुझे गुरु-वुरु मत","कहिए। माँ तो गुरु होती है, चाहे मानो,","चाहे नहीं मानो,"]],[5868,["लेकिन माँ का गुरु होना अलग होता है और जो गुरु","होते हैं, असल में वो बड़े ज़बरदस्त होते हैं।"]],[5875,["एक गुरु साहब हैं, उनको हम बहुत मानते हैं,","बहुत पहुँचे हुए पुरुष हैं,"]],[5879,["उनकी उमर भी 108 साल की है, और वो","हमको मानते हैं माँ की तरह।"]],[5885,["तो एक दिन हमसे कहने लगे कि, \"कोई आदमी","अगर आपको तकलीफ दे तो उसको","मेरे पास भेज दीजिए।\""]],[5889,["अब मुझे क्या पता था कि ये करते क्या हैं?","मैंने कहा, \"अच्छा भई भेज देते हैं।\""]],[5894,["उस महाशय से हमने कहा कि, \"अच्छा जाकर","के फलाने गुरु से जाकर के मिलो।\""]],[5899,["तो एक महीने बाद किसी तरह से बड़ी भीड़","लगी हुई थी, वो अपनी टांगें गर्दन में लटकाए","हुए (अस्पष्ट) ले के आये।"]],[5909,["मैं तो देख के मेरी आँखों में आँसू आ गए,","मैंने कहा, \"ये क्या हुआ?\""]],[5912,["कहने लगे, 'माँ, अब उनके पास मत भेजना","मुझे।' मैंने कहा, \"क्या हुआ?\""]],[5916,["कहने लगे, \"मैं वहाँ गया और आपकी थोड़ी सी","बुराई करी।\" मैंने कहा, \"क्या बुराई की मेरी?\""]],[5920,["कहने लगे, मैंने ये कहा, \"इसको-उसको पार","करातीं हैं, उसको सहज योग देतीं हैं, ये है,","वो है,\" ऐसे मैंने बातें करीं"]],[5926,["तो कहा, \"अच्छा-अच्छा ठीक है, बैठो, कोई","बात नहीं,\" और वो कुछ शेर थे इनके यहाँ,","(अस्पष्ट)"]],[5931,["क्योंकि चलते-फिरते नहीं थे, उनकी टांगें कुछ","(अस्पष्ट), तो वो शेर उनको धक्का मार के","नीचे गिरा दिए"]],[5938,["तो वो बेचारे (अस्पष्ट) हुए नीचे गिर गए,","उनकी दोनों टाँगें टूट गईं।"]],[5942,["चार दिन बाद ऊपर से नीचे रोटियाँ छोड़","दीं, \"अच्छा, तू इनको खा।\""]],[5945,["उसके बाद, पाँच-छह दिन बाद उठा के ले","गए और उनसे कहा,"]],[5948,["\"देखो, ये टाँगें जो हैं गर्दन में डालो और माँ","के पास लटकते हुए जाओ।"]],[5952,["वो ही तुमको ठीक करेगी, मैं नहीं ठीक करूँगा।\"","मैं देख के हैरान, मैंने कहा, \"आखिर क्यों।\""]],[5958,["एक दूसरे महाशय थे, उनको भेजा, तो वो","एकदम दुबले होकर के आ गए। मैंने कहा,","\"क्यों आपको क्या किया भई?\""]],[5966,["कहने लगे, \"मुझे तीन मील ऊपर चढ़वाते थे और","एक शिवजी का जो मंदिर था, उसको दो बाल्टियाँ","लेकर के उसको धो कर के आओ।\""]],[5973,["\"सारा महीने मैंने शिवजी का मंदिर धोया।\"","\"हे भगवान,\" मैंने कहा,\" ये क्या है।\""]],[5977,["तो मैंने उनसे कहा, \"ऐसा क्यों करते हो?\" तो कहने","लगे, \"गधे को गधे का काम। मैं जो माँ नहीं हूँ।\""]],[5982,["\"हम लोग की कुण्डलिनी हमने कैसे जागृत करी?","हमने मेहनत करी, हमने अपनी सफाई करी।\""]],[5988,["\"ऐसे गधों को आपको (अस्पष्ट) दीजिए आप।\"","हमने कहा, \"अच्छा।\" वो बड़े कठिन जीव होते हैं","- मैं गुरु-वुरु नहीं हूँ, मैं तो माँ हूँ।"]],[6000,["आप अपने को गुरु मान लो। मैं ये चाहतीं हूँ","कि आप अपने को गुरु मानो।"]],[6004,["आपको ही गुरु बना देतीं हूँ। अब क्या है?","माँ का तो काम है गुरु बनाना।"]],[6010,["प्रश्न: प्रबुद्ध कुंडलिनी वाले व्यक्ति और","एक धोखेबाज व्यक्ति में भेद कैसे करें?"]],[6016,["श्री माताजी: इसके लिए आपको पहले अपना","आत्मसाक्षात्कार प्राप्त करना होगा।"]],[6018,["जब तक आप आत्मसाक्षात्कारी नहीं हैं, आप","नहीं कर सकते, लेकिन आप कर सकते हैं।"]],[6021,["धोखेबाज व्यक्ति का ध्यान पैसे पर,","आपके पर्स पर होता है,"]],[6025,["या वह आपकी पत्नी के बारे में चिंतित होगा, या","वह आपके घर के बारे में चिंतित होगा क्योंकि"]],[6030,["उनका पहला ध्यान होता है कि आपके पास पैसा","कितना है। अगर कोई बड़ा आदमी गया","तो वो उनका बहुत (अस्पष्ट)"]],[6036,["पर अगर गरीब गया तो वो उससे बात नहीं करते।","आप तो एक मिनिट में पहचान सकते हैं"]],[6040,["ज़रा बुद्धि तो इस्तेमाल करें आप फ़ौरन पहचान","सकते हैं कौन धोखेबाज़ है कौन नहीं।"]],[6047,["पर रियालाइज़ेशन के बाद तो एकदम ही समझ में","आता है क्योंकि वाइब्रेशंस (अस्पष्ट) मानते हैं","आपको बिलकुल समय नहीं लगता है।"]],[6056,["प्रश्न: चक्रों के नाम हिंदी धर्म पर रखे गए हैं। क्या","दूसरे धर्मों में कोई महापुरुष ऐसे नहीं हुए जिसके","नाम पर ये रखे जाते?"]],[6068,["मुसलामानों के मोहम्मद साहब की कहीं चर्चा नहीं","है। क्या कुण्डलिनी में उनका कोई महत्त्व नहीं है?"]],[6077,["श्री माताजी: उनका बहुत योगदान है, सबसे","ज़्यादा उनका योगदान है कुण्डलिनी जागरण में"]],[6082,["क्योंकि उन्होंने जितना नमाज़ बताया है, सारा","नमाज़ कुण्डलिनी के जागरण का तरीका है।"]],[6087,["और ये कहना कि उनके लिए, उन्होंने कहा नहीं है","कुण्डलिनी के चक्रों के बारे में, ये गलत बात है"]],[6093,["क्योंकि बाइबिल में ही लिखा है कि, \"मैं ज्वाला","की भाँति तुम्हारे सामने प्रकट होऊँगा।\""]],[6098,["और इसको उन्होंने 'ट्री ऑफ़ लाइफ बताया","हुआ है' - जीवन का वृक्ष बताया हुआ है।"]],[6103,["तो मोहम्मद साहब ने तो बहुत ही काम किया","है। उनके तो हम बहुत सारे तरीके","इस्तेमाल करते हैं।"]],[6107,["जैसे किसी आदमी में कोई शैतान हो, उसको","किस तरीके से ठीक करना चाहिए,","मोहम्मद साहब ने बताया है।"]],[6113,["उन्होंने सारे कुण्डलिनी के तरीके बताये हैं।","और उनके जो एक हज़ार नाम हैं"]],[6117,["उनको आप पढ़िए तो हरेक नाम से ही","जागरण कुण्डलिनी का हो सकता है"]],[6121,["पर उसको कहने वाला एक जागृत","औलिया होना चाहिए।"]],[6125,["मैं गई थी त्रिची, वहाँ कुछ लोग बैठे","हुए थे, तो उन्होंने पूछा, मैंने पूछा,"]],[6129,["\"भई, तुम लोगों की जात क्या है?\" कहने लगे,","\"माँ, औलिया की भी कोई जात होती है?\""]],[6132,["भई ठीक कहा उन्होंने - कि आप गुणातीत,","कालातीत और धर्मातीत"]],[6138,["एकदम ऐसी जगह पहुँच जाते हैं,","जहाँ पर कि इसका बंधन टूट जाता है।"]],[6142,["मोहम्मद साहब के तो बड़े उपकार हैं - क्योंकि","आप लोग यहाँ पर मुझे हिंदी भाषा में सुन रहे हैं,"]],[6148,["इसलिए मैं चक्रों के बारे में बता रहीं हूँ,","लेकिन चक्रों के नाम जो हैं संस्कृत भाषा में हैं।"]],[6153,["'संस' 'कृत'। संस्कृत भाषा जो है, ये","देवताओं में सबकी है"]],[6156,["लेकिन आप तो मेरे ख्याल से अंग्रेजी भी समझते हैं","और हिंदी भी और फ़ारसी भी।"]],[6161,["क्योंकि मैं सभी भाषाएँ थोड़ा-थोड़ा जानतीं हूँ।"]],[6166,["सहज योगी: बहुत से क्वेश्चन (प्रश्न) मिलते-जुलते हैं","इसलिए उनको जोड़ के उनका प्रश्न किया","जा रहा है।"]],[6175,["प्रश्न: कृपया हमें अपने गुरु के बारे में बताएँ।"]],[6179,["श्री माताजी: हमारे वही गुरु हुए हैं एकनाथजी। ऐसे","इंसान गुरु मिले नहीं कभी भी (अस्पष्ट) गुरु नहीं।"]],[6185,["लेकिन आप मेरे गुरु हैं सच मानो तो।","आप सभी मेरे गुरु हैं।"]],[6190,["मैं हर सहज योगी से कुछ न कुछ सीखतीं हूँ।","क्योंकि आदमी कितना टेढ़ा है ये मैं नहीं","कह सकती।"]],[6195,["इतना टेढ़ा है, इतना पागल, इतना विक्षिप्त कि","मैंने सोचा ही नहीं था कि आदमी होगा।"]],[6199,["एक-एक को देखतीं हूँ मैं कहतीं हूँ, \"हे भगवान्,","ये क्या?\" हर इंसान मेरे लिए गुरु है।"]],[6204,["हरेक से मैं सीखतीं हूँ कि, 'इस आदमी की","तो खोपड़ी ऐसी है।'"]],[6207,["जब से मैं पैदा हुईं हूँ तब से मैंने यही","सीखती रही 'इंसान है।'"]],[6211,["इसकी ऐसी खोपड़ी में कुछ क्यों भरा, इसकी","कुण्डलिनी जागृत क्यों नहीं है,"]],[6215,["इसके पेरमुटेशन-कॉम्बिनेशन क्या हैं,","इसकी क्या विशेषता है, क्या बाधा है?"]],[6220,["ऐसे तो मैं सभी जितने भी गुरु-घंटाल,","जिनको आप लोग कहते हैं,"]],[6223,["सबको मिलने गई थी, एक-एक को देखने","के लिए कि धंधा क्या करते हैं।"]],[6228,["और उनको भी मैंने देखा कि ये लोग तो बिल्कुल","अपरिचित हैं, बिल्कुल अपरिचित हैं।"]],[6234,["और ये लोग इसलिए अपरिचित हैं, कि","परमात्मा के विरोध में जो काम पड़ते/करते हैं"]],[6237,["ये करते हैं, उनके साथ परमात्मा क्या व्यवहार","करेंगे। ये नर्क से भी अपरिचित लोग हैं।"]],[6249,["प्रश्न ॐ नमः शिवाय मन्त्र का उच्चारण किस तरह","करना चाहिए? जैसे आपने कहा कि इससे","हार्ट ट्रबल हो जाता है ....."]],[6257,["श्री माताजी: हाँ, पर पार होने के बाद। आपको","अगर हार्ट ट्रबल है, तो 'ॐ नमः शिवाय'","कहना चाहिए।"]],[6264,["लेकिन पार होने के बाद, उसके पहले नहीं। हो","सकता है कि आपको हार्ट ट्रबल हो जाए","अगर आपकी (अस्पष्ट) हो, हो सकता है"]],[6282,["ये पर्सनल क़्वेशन्स हैं, उनके लिए यही कहना है कि","आप हमारे केंद्र में आकर इनके - ज़रा","पता आप बता दीजिए"]],[6288,["वहाँ आप इन लोगों से मिलिए और ये लोग","आपको 21 तारीख़ मिल सकते हैं।"]],[6296,["21 तारीख़ को शाम को। आप अगर 21 तारीख़","को शाम को उस केंद्र पे जाएँ और उनसे पता करें।"]],[6304,["(वहाँ पर फ़ोन भी है ना?) अब टेलीफोन भी है,","वहाँ पता कर लें और आप जा कर मिलें"]],[6309,["ये लोग आपको सब कुछ समझा देंगे, जिनके","पर्सनल क़्वेशन्स (व्यक्तिगत प्रश्न) हैं,","वो कैसे ठीक होंगे।"]],[6320,["सहज योगी: ये मंदिर है 78 कृष्णा नगर, सफदरजंग","एन्क्लेव। कमल सिनेमा के पास पड़ता है"]],[6329,["और संडे (रविवार) को सुबह, वेडनेसडे (बुधवार)","शाम को और सैटरडे (शनिवार) शाम को,"]],[6337,["सहज योगियों की मीटिंग होती है। कोई और प्रश्न","हों, या आपको कोई तकलीफ हो, तो वहीं","आकर के आप पूछ लीजिये।"]],[6344,["श्री माताजी: पर 21 तारीख़ के बाद विचार नहीं","करिए क्योंकि तब तक ये शायद और किसी","काम में व्यस्त हैं।"]],[6349,["आप कृपया 21 तारीख़ के बाद से, जब भी चाहें,","वहाँ आप फ़ोन कर सकते हैं और जैसा","आपने बताया, आप वहाँ पर ...."]],[6358,["सहज योगी: वैसे सेंटर्स हर जगह में हैं।","दिल्ली में 7-8 सेंटर्स हैं"]],[6364,["जिनका एड्रेस आपको यहाँ हमारा काउंटर है","वहाँ मिल जाएँगे - जगह-जगह में हैं सेण्टर।"]],[6370,["श्री माताजी: काफी जगह में हैं दिल्ली में।"]],[6372,["सहज योगी: हाँ। तो आप एड्रेस ले लीजिये","जब जाने से पहले।"]],[6383,["श्री माताजी: अब जागरण के लिए क्या करना","होगा? सो बहुत सरल चीज़ है।"]],[6387,["मैंने आपसे कहा था कि आप पैर के जूते उतार लें,","क्योंकि ये जो पृथ्वी माता है इससे हमें","बहुत मदद होती है।"]],[6394,["जूते उतार लें, और जूते पीछे की तरफ रख लें,","और दोनों हाथ हमारी ओर इस प्रकार रखें।"]],[6406,["कृपया अपने हाथ मेरी ओर इस प्रकार रखें,","जैसे हम नमाज पढ़ते हैं।"]],[6432,["अब सबसे पहले हमें इस अपने मातृभूमि को","वंदना करनी चाहिए जिन्होंने हमें जन्म दिया"]],[6440,["और ये विशेष योग भूमि है जिस योगभूमि में जन्म","पाने से ही हम अधिकारी हो जाते हैं इस योग","को प्राप्त करें।"]],[6448,["इसलिए उनसे हमें क्षमा माँगनी चाहिए कि","उनके विरोध में हमने जो भी कार्य किया हो,"]],[6453,["और उनसे प्रार्थना करनी चाहिए कि, \"इस वक़्त,","इस मोक्ष के क्षण में, हे माँ, तुम हमारी मदद करो।\""]],[6460,["हाथ जोड़ के और आँख बन्द कर के, पूर्ण ह्रदय से,","उनकी प्रार्थना करें कि, \"हे माँ, इस वक़्त","आप हमारी मदद करें।\""]],[6469,["कृपया इस मातृभूमि, जो सर्वोच्च कोटि की योगभूमि","है, से प्रार्थना करें कि, \"हे माँ, कृपया इस मोक्ष की","घड़ी में मेरी सहायता करें।\""]],[6495,["इसके बाद, हमारे अंदर बसे हुए श्री गणेश को","नमस्कार करके कहना चाहिए"]],[6502,["कि \"श्री गणेश, इस वक्त, इस मोक्ष क्षण में तो आप","मेरा रक्षण करें।\" वो रक्षण करता है"]],[6508,["इसलिए, \"मुझे आप सुबुद्धि दें और मेरा इस वक्त","रक्षण करें,\" ऐसे उनसे विनती करनी चाहिए।"]],[6515,["कृपया अपने भीतर अबोधिता स्वरुप","श्री गणेश से प्रार्थना करें कि,"]],[6519,["\"हे अबोधिता के स्वामी, कृपया मुझे उन सभी","गलतियों के लिए क्षमा करें जो मैंने की हैं,"]],[6526,["और मेरे जीवन के इस विशेष मोक्ष के क्षण का","ध्यान रखें, मुझे वह सभी सुरक्षा प्रदान करें","जो आवश्यक है।\""]],[6538,["त्रिवार करें, तीन बार।"]],[6565,["अब इसके बाद आप दोनों हाथ मेरी ओर इस","तरह से रखें, जैसे नमाज़ में रखे जाते हैं -"]],[6572,["अपने कायदे से गोद में ही दोनों हाथ रख लें।"]],[6579,["लेकिन दोनों हाथ सीधे रहें और दोनों पैर ज़मीन","पर अलग-अलग रखें, ज़मीन को छूते हुए।"]],[6587,["कृपया अपने दोनों हाथों को गोद में रखें और","अपने दोनों पैरों को एक दूसरे से अलग रखें,","धरती माँ को ठीक से स्पर्श करते हुए।"]],[6596,["कृपया अपनी टोपियाँ उतार लें, यदि आपके पास हैं,","क्योंकि हमें ब्रह्मरंध्र को खोलना है, जो कि","फॉन्टानेल हड्डी का क्षेत्र है।"]],[6602,["अगर आपके सर में टोपी वगैरा हो,","वो निकाल लें क्योंकि हम तो माँ हैं"]],[6605,["और माँ से कोई प्रोटोकॉल नहीं होता है, इसलिए","टोपी-ओपी सब निकाल के आराम से बैठिए।"]],[6617,["अब सर्वप्रथम जानिए कि आपके ह्रदय में आत्मा","होता है, इसलिए जो आपका राइट हैंड है","उसे आप ह्रदय पे रखें।"]],[6628,["आपका जो लेफ्ट हैंड है वो आपकी इच्छा शक्ति","है, इसलिए पूरी समय इस तरह से बना रहे"]],[6635,["मेरी ओर कि जैसे आपको इच्छा है कि","आप अपना आत्मसाक्षात्कार पाएँ।"]],[6644,["इस इच्छा को जताने के लिए लेफ्ट हैंड, पूरी","समय अपनी गोद में रखा हुआ, मेरी ओर रखें।"]],[6650,["कृपया अपना बायाँ हाथ मेरी ओर रखें, जिससे यह","पता चलता है कि आप अपनी इच्छा शक्ति से","आत्म-साक्षात्कार प्राप्त करना चाहते हैं।"]],[6660,["और दूसरे हाथ, दाहिने हाथ को, कृपया इसे","अपने हृदय पर रखें, क्योंकि हृदय में आपकी","आत्मा निवास करती है।"]],[6668,["इस समय आपको तीन बार कहना होगा","या एक प्रश्न पूछना होगा -"]],[6676,["कृपया इसे धार्मिक रूप से, ठीक से करें और","मुझे यकीन है कि आपकी कुंडलिनी जाग जाएगी।"]],[6680,["अपने भीतर एक प्रश्न पूछें, ज़ोर से नहीं,","\"माँ, क्या मैं आत्मा हूँ?\""]],[6686,["यहाँ हाथ रख कर के, आप ह्रदय पे हाथ रख","कर के, पूर्ण ह्रदय से आप एक सवाल पूँछें,"]],[6692,["\"क्या मैं आत्मा हूँ? माँ, क्या मैं आत्मा हूँ,\"","- इस तरह से तीन बार ये प्रश्न करें।"]],[6699,["कृपया यह प्रश्न तीन बार पूछें।"]],[6706,["सब अपनी ओर चित्त रखें दूसरों की ओर नहीं।","इस वक़्त अपनी ओर चित्त।"]],[6726,["अब यही हाथ नीचे पेट पर लेफ्ट साइड में रखें।","पेट पर नीचे लेफ्ट साइड में रखें।"]],[6735,["यहाँ पे गुरु का तत्व है - मैंने आपसे पहले","ही बताया था।"]],[6740,["कृपया इस दाहिने हाथ को अपने पेट के ऊपरी","हिस्से में बायीं ओर रखें। ये गुरु का तत्व है।"]],[6749,["यहाँ, आपको फिर से तीन बार प्रश्न पूछना होगा,","\"माँ, यदि मैं आत्मा हूँ, तो क्या मैं अपने","स्वयं का गुरु हूँ?\""]],[6756,["यहाँ पर आप एक प्रश्न मुझे करें तीन बार कि, \"माँ,","अगर मैं आत्मा हूँ तो क्या मैं ही मेरा गुरु हूँ?\""]],[6764,["ऐसे तीन बार प्रश्न करें। आप अपने ही आप से","अपने चक्रों में शक्ति भर रहे हैं।"]],[6788,["तीन बार करने के बाद अब यही हाथ आप नीचे","बिल्कुल, पेट के नीचे के हिस्से में रखें।"]],[6795,["इस जगह स्वाधिष्ठान चक्र लेफ्ट साइड में है।","ये चक्र जो है ये शुद्ध विद्या का चक्र है।"]],[6802,["यहाँ पे शुद्ध विद्या पाई जाती है। शुद्ध विद्या","माने वो विद्या, जिससे कि आप परमात्मा का","सारा कार्य जानते हैं,"]],[6810,["उनकी शक्ति को जानते हैं, और उस शक्ति","का विवरण करना, उसका आवरण करना,"]],[6815,["उसको किस तरह से प्रसारित करना, उसका किस","तरीके से उपयोग करना, ये सब क्रियाएं आप","जानते हैं - इसे शुद्ध विद्या कहते हैं।"]],[6822,["परमात्मा के क्या कायदे कानून हैं, उसे भी","आप जानते हैं।"]],[6826,["ये सारी शुद्ध विद्या है और बाकी सारी","अशुद्ध विद्याएँ हैं,"]],[6830,["इसलिए आप यहाँ हाथ रखकर के और ये","कहें कि, \"माँ मुझे शुद्ध विद्या दीजिए।\""]],[6836,["बात ये है कि आप स्वतंत्र हैं, मैं आप पे कोई","ज़बरदस्ती नहीं कर सकती।"]],[6840,["आपको माँगना होगा कि, \"माँ, मुझे","शुद्ध विद्या दीजिए।\""]],[6844,["कृपया अपना दाहिना हाथ अपने पेट के निचले","हिस्से पर रखें और शुद्ध विद्या माँगें -"]],[6851,["- यही सच्चा ज्ञान है। सच्चा ज्ञान ईश्वर की","शक्ति, उनके नियमों, विनियमन"]],[6860,["और उनकी शक्ति हमारे माध्यम से कैसे काम","करती है, इसका ज्ञान है।"]],[6863,["इसलिए, आपको इसे माँगना होगा क्योंकि आप","स्वतंत्र हैं - आपको यह चाहिए या नहीं,"]],[6867,["मैं इसे आप पर थोप नहीं सकती, इसलिए आपको","इसे माँगना होगा, छह बार।"]],[6871,["छह बार कहिए, \"माँ, मुझे शुद्ध विद्या दीजिए\"","- बहुत सिंपल चीज़ है।"]],[6885,["इससे जितनी भी अशुद्ध विद्याएँ हैं, वो अपने","आप ही गलित हो जायेंगीं।"]],[6898,["अब आप यही राइट हैंड ऊपर उठा कर के","और लेफ्ट हैंड साइड में अपने पेट पर रखें।"]],[6908,["लेफ्ट हैंड साइड में फिर से वहीं पेट पे","रखें जहाँ गुरु तत्व है।"]],[6914,["इस गुरु तत्व पे रखने पर अब शुद्ध विद्या की","शुरुआत हो गई है, इसलिए आपको इस जगह","कुण्डलिनी के चढ़ावे के लिए कहना चाहिए"]],[6922,["कि, \"माँ, मैं स्वयं का गुरु हूँ।\" पूर्ण विश्वास के साथ ये","कहना पड़ेगा, तो कुण्डलिनी ऊपर चढ़ेगी।"]],[6932,["राइट हैंड, राइट हैंड रखना है, लेफ्ट हैंड हमारी","ओर। लेफ्ट हैंड हमारी ओर - कुछ लोग","गलती कर बैठे हैं।"]],[6940,["लेफ्ट हैंड हमारी ओर करिए, राइट हैंड पेट में","लेफ्ट हैंड साइड में रखें और कहें कि, \"माँ,","मैं स्वयं का गुरु हूँ\" - पूर्ण विश्वास से कहें।"]],[6954,["कृपया अपना दाहिना हाथ अपने पेट के ऊपरी","भाग पर रखें और पूर्ण विश्वास से कहें कि,","\"माँ, मैं अपने स्वयं का गुरु हूँ।\""]],[6968,["ये दस बार कहिए। कृपया इसे दस बार कहें।"]],[6990,["अब जो लोग कर नहीं रहे हैं, फिर बाद में","कहेंगे कि, \"माँ हमारी जागृत नहीं हुई।\""]],[6994,["इतना सा करने में क्या जाता है? कर के","देखिए, आपकी अपनी शक्ति है, आपका","अपना सब कुछ है, पाने का है।"]],[7004,["अच्छा दस मर्तबा कहिए। कृपया इसे दस","बार कहिए।"]],[7009,["पूर्ण विश्वास के साथ, पूर्ण आत्मविश्वास के","साथ कहें कि, \"माँ, मैं स्वयं का गुरु हूँ।\""]],[7018,["इस तरह से आपका गुरु तत्व जागृत हो जायेगा।"]],[7037,["अब फिर से ये हाथ अपने ह्रदय पे रखें। फिर से","ये हाथ अपने ह्रदय पे रखें - आँखें न खोलें।"]],[7046,["ह्रदय पे रखकर के, आप पूर्ण विश्वास के साथ","कहिए कि, \"माँ मैं आत्मा हूँ\" - क्योंकि आप","आत्मा हीं हैं।"]],[7055,["मन, बुद्धि, अहंकार आदि आप नहीं, आप शुद्ध","आत्मा हैं। इसलिए आप कहिए कि,","'माँ, मैं आत्मा हूँ।'"]],[7062,["कृपया अब अपने हृदय पर दाहिना हाथ रखें और","पूरे विश्वास के साथ कहें, \"माँ, मैं आत्मा हूँ।\""]],[7070,["इसे बारह बार कहें क्योंकि इस केंद्र में बारह","पंखुड़ियाँ हैं, इसीलिए हमारे बारह ज्योतिर्लिंग हैं।"]],[7111,["अब विशुद्धि चक्र पे काम करते हैं। विशुद्धि","चक्र के लिए लेफ्ट साइड में -"]],[7117,["लेफ्ट हैंड तो हमारी तरफ पूरी तरह बना ही रहेगा,","राइट हैंड को उठा कर के और अपनी गर्दन के","पास कंधे पे रखें।"]],[7125,["गर्दन के पास कंधे पर ज़ोर से पकड़िए,","सामने से। सामने से पकड़िए ज़ोर से।"]],[7133,["उंगलियाँ ज़रा पीछे ले जा कर के ज़ोर से","पकड़िए। ये चक्र बहुत ज़रूरी है"]],[7138,["और अधिकतर शहरों में पकड़ा जाता है।","आपको जानना चाहिए कि आप आत्मा हैं","और आत्मा निर्दोष है।"]],[7146,["इसलिए आप यहाँ पर कहिए कि, \"माँ,","मैं आत्मा हूँ और मैं पूर्णतया निर्दोष हूँ।\""]],[7155,["कुछ भी छोटी गलतियाँ इधर-उधर की हैं, सो","उसके बारे में कुछ भी सोचना नहीं इस वक़्त"]],[7161,["क्योंकि परमात्मा जो हैं ये प्रेम के सागर, दया","के सागर तो हैं हीं लेकिन सब से ज़्यादा","क्षमा के सागर हैं।"]],[7170,["कृपया अपना हाथ अपनी गर्दन पर कंधे","के पास रखें और उसे जोर से दबाएँ।"]],[7179,["इस स्थान पर आपको कहना होगा, \"माँ, मैं आत्मा हूँ","और मैं बिल्कुल भी दोषी नहीं हूँ क्योंकि आत्मा","दोषी नहीं हो सकता।\""]],[7211,["अब आपका यहाँ पर सोलह मर्तबा कहना होगा,","आपको सोलह बार कहना होगा, क्योंकि यह","श्री कृष्ण का चक्र है,"]],[7260,["अब यह कहा जाए कि, \"मैं बिल्कुल निर्दोष हूँ,\"","और ये भी कहा जाए उसी के साथ"]],[7266,["कि, \"परमात्मा अगर मैंने कोई गलती कर दी हो,","तो उसे माफ़ कर दें।\""]],[7270,["ये कहने के बाद, सोलह मर्तबा कहने के बाद, आप","कहिए, अपना हाथ राइट हैंड सिर के पीछे","में रखिए,"]],[7278,["इस जगह रख कर के आप कहिए कि, \"अगर मैंने","कोई गलती की हो, तो आप मुझे क्षमा कर दीजिए।\""]],[7299,["सिर के पीछे में हाथ रख के कहें,","लेकिन निर्दोष रह के।"]],[7303,["आप में तो कोई दोष नहीं सिर्फ कह दीजिए कि,","\"मुझसे कोई गलती हो, सो उसे माफ़ कर दीजिए।\""]],[7319,["हम्म। अब ये हाथ सामने की ओर अपने माथे","पर रखें, अपने कपाल पे रखें।"]],[7328,["कृपया इस हाथ को अपने माथे पर आड़ा रखें।"]],[7334,["इस जगह आपको कहना चाहिए कि,","\"माँ, मैंने सब को माफ़ कर दिया।\""]],[7340,["सब को माफ़ कर दीजिए। ये बहुत आसान है।"]],[7344,["कहना बहुत आसान है और जो लोग कहते हैं कि","हम नहीं कर सकते, वो बड़े गलत फहमी में हैं।"]],[7349,["क्योंकि अगर आप किसी को माफ़ नहीं कर","रहे हैं, तो आप अपने को ही दुख दे रहे हैं"]],[7353,["दूसरों को नहीं, इसलिए कहिए, पूरे ह्रदय से","कहिए कि, \"माँ, मैंने सब को माफ़ कर दिया।\""]],[7363,["अपने को भी माफ़ करिए, अपने को भी","माफ़ करिए और सब को माफ़ करिए।"]],[7372,["[अलग से - यह बाईं विशुद्धि से आया है।]"]],[7377,["अब यही हाथ सर पे रखें, सर पर यहाँ पर","जहाँ पर कि आपका तालु भाग है।"]],[7384,["कृपया ये हाथ अपने फॉन्टानेल हड्डी क्षेत्र पर रखें","और अपनी हथेली को सिर को छूते हुए इसे नीचे","दबाएं और इसे दक्षिणावर्त तरीके से रखें।"]],[7393,["इसे गोल घुमाइए, घडी की दिशा में घुमाइए,","और इस वक़्त सात मर्तबा ये कहिए कि,","\"माँ, मुझे आत्मसाक्षात्कार चाहिए।\""]],[7402,["कारण, ये यहाँ पर ब्रह्मरंध्र है और इसी से जब","कुण्डलिनी छिदती है, तभी आत्मसाक्षात्कार","प्राप्त होता है।"]],[7409,["लेकिन, मैं आप पर फिर ज़बरदस्ती किसी भी","चीज़ की कभी भी नहीं कर सकती।"]],[7413,["इसलिए आपको स्वेच्छा से कहना चाहिए","कि, \"माँ, मुझे आत्मसाक्षात्कार दीजिए।\""]],[7418,["आप स्वतंत्र हैं, जो चाहें करें। उसको घुमा","कर के और सात बार कहें कि, \"माँ, आप","कृपया मुझे आत्मसाक्षात्कार दें।\""]],[7426,["कृपया इस बिंदु पर अपने हाथ को दक्षिणावर्त दिशा","में घुमाते हुए अपने आत्म-बोध के लिए मांगें"]],[7432,["क्योंकि मैं इसे आप पर थोप नहीं सकती।","मैं नहीं कर सकती, आप स्वतंत्र हैं,"]],[7436,["इसलिए आपको यह माँगना होगा कि, \"माँ, कृपया","मुझे मेरा आत्म-साक्षात्कार दें।\" इसे सात बार कहें।"]],[7450,["अब दोनों हाथ हमारी ओर करें।","आँख बन्द रखें, आँख न खोलें।"]],[7458,["अब लेफ्ट हैंड सर पे रख के देखें कि क्या","ठंडक आ रही है, ऊपर अधांतरिक।"]],[7463,["कृपया अपना हाथ अपने सिर से थोड़ा ऊपर रखें","और फॉन्टानेल हड्डी को देखें कि क्या","ठंडी हवा आ रही है।"]],[7470,["बस इसे दबाने का प्रयास करें, हो सकता है कि","आपको कुछ बाहर आता हुआ दिखाई दे।"]],[7477,["ये बहुत सूक्ष्म है। अब लेफ्ट हैंड नीचे कर","के राइट हैंड से देखें। बेहतर है।"]],[7493,["बहुतों के राइट हैंड में नहीं आता है। राइट","हैंड ऐसे रखें और लेफ्ट हैंड ऐसा करें"]],[7498,["थोड़ी देर के लिए - पाँच मिनिट। पाँच मिनिट","भी नहीं, थोड़ी देर के लिए।"]],[7502,["राइट हैंड हमारी ओर और लेफ्ट हैंड बाहर -","जिससे संतुलन आ जायेगा।"]],[7509,["राइट हैंड में धीरे-धीरे आने लगेगा। लेफ्ट","हैंड इस तरह से पीछे की ओर।"]],[7517,["विचार नहीं करें, निर्विचारिता में। हमारी ओर","देखें निर्विचारिता में।"]],[7524,["अब लेफ्ट हैंड हमारी ओर और राइट हैंड ऐसे।","आ रहा है ठंडा? हाथ में देखिए थोड़ी-थोड़ी","ठंडक आ रही क्या?"]],[7543,["अब दोनों हाथ ऊपर करिए और ये पूछिए","कि, \"माँ क्या यही ब्रह्मशक्ति है?\""]],[7549,["कृपया पूछें, \"क्या यह ब्रह्मशक्ति है?","क्या यह ईश्वर की सर्वव्यापी शक्ति है?\""]],[7554,["बस अपने दिल में पूछें और आप अपने हाथों में","ठंडी हवा बहती हुई महसूस करेंगे।","सीधा, इस तरह।"]],[7564,["अब देखिए हाथ। आ रही है ठंडक? देखिए हाथ","में ठंडक आ रही है, आप लोगों को।"]],[7575,["हम यहाँ और दो दिन आएँगे - सब ठीक से","परिपक्व कर देंगे।"]],[7579,["लेकिन देखिए ठंडक हाथ में आ रही कि नहीं?","सर में देखिए आ रही कि नहीं?"]],[7584,["सर के ऊपर। दूसरे हाथ से देखिए। इस","वक़्त विचार नहीं करें, निर्विचारिता में।"]],[7592,["महसूस करो - आ रही? अच्छा।"]],[7598,["अब एक चीज़ देखें कि आप अपनी कुण्डलिनी","कैसे जागृत करेंगे ये बहुत ज़रूरी है"]],[7603,["क्योंकि आपको घर जाकर के ऐसा लगेगा कि फिर","से खो गया। इसलिए इसको जागृत कैसे करना","ये बहुत आसान चीज़ है।"]],[7609,["आप अपनी कुण्डलिनी जागृत कर सकते हैं,","क्योंकि मैंने कहा है आप ही अपने गुरु हो जाते हैं।"]],[7615,["तो लेफ्ट हैंड आप ऐसा रखें - चाहे हमारा","फोटू हो तो अच्छा है - उसपे एक दीप जला लें।"]],[7619,["लेफ्ट हैंड इस तरह से रख लेने का और राइट हैंड","जो है उससे अपने को पहले कवच लेना पड़ता है,"]],[7625,["बंधन लेना पड़ता है, क्योंकि बंधन नहीं लेंगे तो","कोई भी दुष्ट प्रवृत्ति है - अभी बाहर ही आप","जाएंगे तो आपको पकड़ लेगी।"]],[7631,["इसलिए आपको तकलीफ सी थोड़ी सी लगेगी","कि क्या पता नहीं हो रहा है? अभी तक तो ठीक","थे, अब पता नहीं क्या हो गया है?"]],[7637,["तो इसको, राइट हैंड को, इस तरह से आप लेफ्ट","हैंड से ऊपर उठाइए"]],[7641,["और ऐसे उठा कर के सर पे से नीचे लीजिए।","अब आपने लेफ्ट साइड उठा ली"]],[7646,["और ऊपर से ग्रेस उठाई है। इस प्रकार हमें","सात बार करना होता है। लीजिए।"]],[7656,["फिर से वापस सर पे से ही ले आइये।","फिर से एक हुआ, फिर ये दो बार।"]],[7664,["ये सात चक्रों पे हम बंधन दे रहे हैं - बहुत","श्रद्धापूर्ण करें - और ये तीन बार और ये चार बार"]],[7678,["और ये पाँच बार, और ये छह बार - पूर्ण श्रद्धा","से - और अब ये सातवें बार हो गया"]],[7689,["ये आपने अपने को अपने को कवच दे दिया है।"]],[7692,["अब ये हाथ सामने ऐसे रखें, बिल्कुल सीधे","तरीके से, यूँ हाथ रखें।"]],[7696,["यहाँ कुण्डलिनी का स्थान है, आपने हाथ","बैठे-बैठे ऐसे रख लिए हैं।"]],[7700,["अब इसके सामने से कुण्डलिनी चढाने के लिए -","ये तो आपकी इच्छा शक्ति, ये क्रिया शक्ति है,"]],[7706,["इसलिए ये हाथ ऊपर, सामने नीचे इस तरह से","क्लॉकवाईस घुमाना पड़ेगा और इसी से आप","देखिए आपकी (अस्पष्ट) आप"]],[7882,["किसी साहब ने वहाँ से किताब ली है बड़ी वाली","और पेमेंट नहीं की, कृपया वह किताब","वापस कर दें।"]],[7889,["किसी ने वहाँ से किताब ले ली है और उसका","पैसा नहीं दिया है - कृपया वापस करें।"]]]);
